const questionnaireHtml = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>שאלון אפיון למערכת הזמנות</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --bg: #f6f7f8;\n      --panel: #ffffff;\n      --ink: #17202a;\n      --muted: #64707d;\n      --line: #dfe5eb;\n      --accent: #1c7c54;\n      --accent-dark: #145c3e;\n      --warn: #8a5a00;\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    body {\n      margin: 0;\n      font-family: Arial, \"Helvetica Neue\", sans-serif;\n      background: var(--bg);\n      color: var(--ink);\n      line-height: 1.55;\n    }\n\n    main {\n      width: min(920px, calc(100% - 28px));\n      margin: 0 auto;\n      padding: 28px 0 42px;\n    }\n\n    header {\n      margin-bottom: 22px;\n    }\n\n    h1 {\n      margin: 0 0 8px;\n      font-size: 30px;\n      line-height: 1.2;\n    }\n\n    .intro {\n      margin: 0;\n      color: var(--muted);\n      font-size: 16px;\n    }\n\n    form {\n      display: grid;\n      gap: 14px;\n    }\n\n    section {\n      background: var(--panel);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 18px;\n    }\n\n    h2 {\n      margin: 0 0 14px;\n      font-size: 20px;\n    }\n\n    label {\n      display: block;\n      font-weight: 700;\n      margin-bottom: 7px;\n    }\n\n    .field {\n      margin-bottom: 16px;\n    }\n\n    .field:last-child {\n      margin-bottom: 0;\n    }\n\n    input,\n    textarea,\n    select {\n      width: 100%;\n      border: 1px solid #cfd8e3;\n      border-radius: 7px;\n      padding: 11px 12px;\n      font: inherit;\n      color: var(--ink);\n      background: #fff;\n    }\n\n    textarea {\n      min-height: 92px;\n      resize: vertical;\n    }\n\n    .choices {\n      display: grid;\n      gap: 8px;\n    }\n\n    .choice {\n      display: flex;\n      align-items: flex-start;\n      gap: 9px;\n      padding: 9px 10px;\n      border: 1px solid var(--line);\n      border-radius: 7px;\n      background: #fbfcfd;\n      font-weight: 400;\n    }\n\n    .choice input {\n      width: auto;\n      margin-top: 4px;\n    }\n\n    .hint {\n      margin-top: 6px;\n      color: var(--muted);\n      font-size: 13px;\n    }\n\n    .actions {\n      position: sticky;\n      bottom: 0;\n      display: flex;\n      flex-wrap: wrap;\n      gap: 10px;\n      padding: 12px 0 0;\n      background: linear-gradient(to top, var(--bg) 70%, rgba(246, 247, 248, 0));\n    }\n\n    button {\n      border: 0;\n      border-radius: 7px;\n      padding: 11px 16px;\n      font: inherit;\n      font-weight: 700;\n      cursor: pointer;\n    }\n\n    .primary {\n      background: var(--accent);\n      color: #fff;\n    }\n\n    .primary:hover {\n      background: var(--accent-dark);\n    }\n\n    .secondary {\n      background: #e7ecef;\n      color: var(--ink);\n    }\n\n    .notice {\n      display: none;\n      margin-top: 10px;\n      color: var(--accent-dark);\n      font-weight: 700;\n    }\n\n    .warning {\n      color: var(--warn);\n    }\n\n    @media (max-width: 640px) {\n      main {\n        width: min(100% - 18px, 920px);\n        padding-top: 18px;\n      }\n\n      h1 {\n        font-size: 24px;\n      }\n\n      section {\n        padding: 14px;\n      }\n\n      .actions {\n        display: grid;\n      }\n    }\n  </style>\n</head>\n<body>\n  <main>\n    <header>\n      <h1>שאלון קצר לאפיון מערכת הזמנות</h1>\n      <p class=\"intro\">המטרה היא להבין איך העסק עובד היום, כדי לבנות מערכת CRM והזמנות שמתאימה בפועל לעבודה היומיומית.</p>\n    </header>\n\n    <form id=\"questionnaire\">\n      <section>\n        <h2>פרטי העסק</h2>\n        <div class=\"field\">\n          <label for=\"businessName\">שם העסק</label>\n          <input id=\"businessName\" name=\"שם העסק\" autocomplete=\"organization\">\n        </div>\n        <div class=\"field\">\n          <label for=\"contactName\">שם איש קשר</label>\n          <input id=\"contactName\" name=\"שם איש קשר\" autocomplete=\"name\">\n        </div>\n        <div class=\"field\">\n          <label for=\"contactPhone\">טלפון</label>\n          <input id=\"contactPhone\" name=\"טלפון\" autocomplete=\"tel\">\n        </div>\n      </section>\n\n      <section>\n        <h2>היקף פעילות</h2>\n        <div class=\"field\">\n          <label for=\"customerCount\">כמה לקוחות קיימים יש בערך?</label>\n          <input id=\"customerCount\" name=\"כמות לקוחות קיימים\" placeholder=\"לדוגמה: 200 / 800 / לא יודע\">\n        </div>\n        <div class=\"field\">\n          <label for=\"ordersCount\">כמה הזמנות יש בערך ביום או בשבוע?</label>\n          <input id=\"ordersCount\" name=\"כמות הזמנות\" placeholder=\"לדוגמה: 10 ביום / 60 בשבוע\">\n        </div>\n        <div class=\"field\">\n          <label for=\"productCount\">כמה מוצרים / שקים שונים יש בערך בקטלוג?</label>\n          <input id=\"productCount\" name=\"כמות מוצרים\" placeholder=\"לדוגמה: 40 / 150 / לא יודע\">\n        </div>\n      </section>\n\n      <section>\n        <h2>לקוחות והזמנות</h2>\n        <div class=\"field\">\n          <label>האם לקוח יכול להזמין כמה מוצרים באותה הזמנה?</label>\n          <div class=\"choices\">\n            <label class=\"choice\"><input type=\"radio\" name=\"כמה מוצרים בהזמנה\" value=\"כן\"> כן</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"כמה מוצרים בהזמנה\" value=\"לא, בדרך כלל מוצר אחד\"> לא, בדרך כלל מוצר אחד</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"כמה מוצרים בהזמנה\" value=\"לא בטוח\"> לא בטוח</label>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label for=\"manualOrders\">באילו מקרים בעל העסק יפתח הזמנה ידנית?</label>\n          <textarea id=\"manualOrders\" name=\"מקרים להזמנה ידנית\" placeholder=\"לדוגמה: לקוחות מבוגרים, הזמנות טלפוניות, לקוח שלא מסתדר עם האתר\"></textarea>\n        </div>\n        <div class=\"field\">\n          <label for=\"specialCustomers\">האם יש לקוחות עם תנאים מיוחדים?</label>\n          <textarea id=\"specialCustomers\" name=\"לקוחות עם תנאים מיוחדים\" placeholder=\"לדוגמה: מחיר קבוע, הנחה, תשלום אחרי אספקה, חוב פתוח\"></textarea>\n        </div>\n      </section>\n\n      <section>\n        <h2>קטלוג ומחירים</h2>\n        <div class=\"field\">\n          <label>איך נכון להציג מוצרים?</label>\n          <div class=\"choices\">\n            <label class=\"choice\"><input type=\"radio\" name=\"מבנה קטלוג\" value=\"מותג/סדרה ואז בחירת סוג, טעם ומשקל\"> מותג/סדרה ואז בחירת סוג, טעם ומשקל</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"מבנה קטלוג\" value=\"רשימת שקים נפרדים\"> רשימת שקים נפרדים</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"מבנה קטלוג\" value=\"לא משנה לי\"> לא משנה לי</label>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label for=\"priceRules\">איך מחירים מיוחדים והנחות עובדים היום?</label>\n          <textarea id=\"priceRules\" name=\"כללי מחירים והנחות\" placeholder=\"לדוגמה: יש לקוחות עם מחיר קבוע, מבצעים לפי מוצר, הנחות לפי לקוח\"></textarea>\n        </div>\n        <div class=\"field\">\n          <label for=\"substitutes\">האם יש מוצרים תחליפיים כשמוצר חסר?</label>\n          <textarea id=\"substitutes\" name=\"מוצרים תחליפיים\" placeholder=\"לדוגמה: אם אין עוף מציעים כבש, אם אין 12 קג מציעים 2 של 6 קג\"></textarea>\n        </div>\n      </section>\n\n      <section>\n        <h2>משלוחים</h2>\n        <div class=\"field\">\n          <label>איך החלוקה מתבצעת היום?</label>\n          <div class=\"choices\">\n            <label class=\"choice\"><input type=\"checkbox\" name=\"שיטת חלוקה\" value=\"לפי ימים קבועים\"> לפי ימים קבועים</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"שיטת חלוקה\" value=\"לפי אזורים\"> לפי אזורים</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"שיטת חלוקה\" value=\"לפי עיר/שכונה\"> לפי עיר/שכונה</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"שיטת חלוקה\" value=\"ידנית לפי מה שנוח\"> ידנית לפי מה שנוח</label>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label for=\"deliveryDays\">האם יש ימי חלוקה קבועים?</label>\n          <input id=\"deliveryDays\" name=\"ימי חלוקה קבועים\" placeholder=\"לדוגמה: ראשון ושלישי באזור המרכז\">\n        </div>\n        <div class=\"field\">\n          <label for=\"deliveryAreas\">אילו אזורים / ערים העסק משרת?</label>\n          <textarea id=\"deliveryAreas\" name=\"אזורי שירות\"></textarea>\n        </div>\n        <div class=\"field\">\n          <label>האם לקוח צריך לבחור מועד אספקה?</label>\n          <div class=\"choices\">\n            <label class=\"choice\"><input type=\"radio\" name=\"בחירת מועד אספקה\" value=\"כן, הלקוח בוחר מועד זמין\"> כן, הלקוח בוחר מועד זמין</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"בחירת מועד אספקה\" value=\"לא, העסק קובע ומעדכן\"> לא, העסק קובע ומעדכן</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"בחירת מועד אספקה\" value=\"לא בטוח\"> לא בטוח</label>\n          </div>\n          <div class=\"hint\">כרגע ידוע שצריך התראה של יומיים מראש.</div>\n        </div>\n      </section>\n\n      <section>\n        <h2>תשלומים וחשבוניות</h2>\n        <div class=\"field\">\n          <label>אילו אמצעי תשלום קיימים בפועל?</label>\n          <div class=\"choices\">\n            <label class=\"choice\"><input type=\"checkbox\" name=\"אמצעי תשלום\" value=\"קישור תשלום משולם\"> קישור תשלום משולם</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"אמצעי תשלום\" value=\"bit דרך משולם\"> bit דרך משולם</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"אמצעי תשלום\" value=\"Google Pay דרך משולם\"> Google Pay דרך משולם</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"אמצעי תשלום\" value=\"מזומן לשליח\"> מזומן לשליח</label>\n            <label class=\"choice\"><input type=\"checkbox\" name=\"אמצעי תשלום\" value=\"העברה בנקאית\"> העברה בנקאית</label>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label for=\"cashInvoice\">איך מפיקים חשבונית / קבלה על מזומן לשליח?</label>\n          <textarea id=\"cashInvoice\" name=\"חשבונית על מזומן לשליח\" placeholder=\"לדוגמה: דרך משולם ידנית, אחרי שהשליח חוזר, דרך מערכת אחרת\"></textarea>\n        </div>\n        <div class=\"field\">\n          <label for=\"failedPayments\">מה עושים היום עם לקוח שלא שילם?</label>\n          <textarea id=\"failedPayments\" name=\"טיפול באי תשלום\" placeholder=\"לדוגמה: מתקשרים אליו, לא מוציאים משלוח, מסמנים חוב\"></textarea>\n        </div>\n      </section>\n\n      <section>\n        <h2>עבודה יומיומית</h2>\n        <div class=\"field\">\n          <label>איפה בעל העסק יעבוד עם המערכת בעיקר?</label>\n          <div class=\"choices\">\n            <label class=\"choice\"><input type=\"radio\" name=\"מכשיר עבודה עיקרי\" value=\"טלפון\"> טלפון</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"מכשיר עבודה עיקרי\" value=\"מחשב\"> מחשב</label>\n            <label class=\"choice\"><input type=\"radio\" name=\"מכשיר עבודה עיקרי\" value=\"גם וגם\"> גם וגם</label>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label for=\"currentPain\">מה הכי מפריע היום בהתנהלות הקיימת?</label>\n          <textarea id=\"currentPain\" name=\"כאבים עיקריים היום\"></textarea>\n        </div>\n        <div class=\"field\">\n          <label for=\"success\">מה ייחשב הצלחה מבחינתך אחרי חודש שימוש?</label>\n          <textarea id=\"success\" name=\"מדד הצלחה אחרי חודש\"></textarea>\n        </div>\n      </section>\n\n      <section>\n        <h2>הערות נוספות</h2>\n        <div class=\"field\">\n          <label for=\"notes\">כל דבר נוסף שחשוב שנדע</label>\n          <textarea id=\"notes\" name=\"הערות נוספות\"></textarea>\n        </div>\n      </section>\n\n      <div class=\"actions\">\n        <button class=\"primary\" type=\"button\" id=\"copyAnswers\">העתקת התשובות</button>\n        <button class=\"secondary\" type=\"button\" id=\"downloadAnswers\">הורדת קובץ תשובות</button>\n        <button class=\"secondary\" type=\"reset\">ניקוי הטופס</button>\n      </div>\n      <div class=\"notice\" id=\"notice\">התשובות הועתקו. אפשר להדביק אותן בוואטסאפ או במייל.</div>\n      <p class=\"hint warning\">הטופס לא שולח מידע לשרת. אחרי המילוי יש ללחוץ על העתקת התשובות או הורדת קובץ.</p>\n    </form>\n  </main>\n\n  <script>\n    const form = document.getElementById('questionnaire');\n    const notice = document.getElementById('notice');\n\n    function collectAnswers() {\n      const data = new FormData(form);\n      const grouped = {};\n\n      for (const [key, value] of data.entries()) {\n        if (!value || !String(value).trim()) continue;\n        if (!grouped[key]) grouped[key] = [];\n        grouped[key].push(String(value).trim());\n      }\n\n      const lines = ['שאלון אפיון מערכת הזמנות', ''];\n      for (const [key, values] of Object.entries(grouped)) {\n        lines.push(`${key}: ${values.join(', ')}`);\n      }\n\n      if (lines.length === 2) {\n        lines.push('לא מולאו תשובות עדיין.');\n      }\n\n      return lines.join('\\n');\n    }\n\n    document.getElementById('copyAnswers').addEventListener('click', async () => {\n      const text = collectAnswers();\n\n      try {\n        await navigator.clipboard.writeText(text);\n        notice.style.display = 'block';\n      } catch (error) {\n        const area = document.createElement('textarea');\n        area.value = text;\n        document.body.appendChild(area);\n        area.select();\n        document.execCommand('copy');\n        area.remove();\n        notice.style.display = 'block';\n      }\n    });\n\n    document.getElementById('downloadAnswers').addEventListener('click', () => {\n      const text = collectAnswers();\n      const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement('a');\n      link.href = url;\n      link.download = 'drive-dog-questionnaire-answers.txt';\n      document.body.appendChild(link);\n      link.click();\n      link.remove();\n      URL.revokeObjectURL(url);\n    });\n  </script>\n</body>\n</html>\n";
const proposalHtml = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>הצעת MVP - Drive Dog</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --bg: #f4f6f5;\n      --paper: #ffffff;\n      --ink: #14211c;\n      --muted: #5f6e68;\n      --line: #dce4df;\n      --green: #176b4d;\n      --green-2: #0f4935;\n      --gold: #c18a28;\n      --blue: #24506d;\n      --soft: #eef4f1;\n      --warn: #fff5df;\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    body {\n      margin: 0;\n      font-family: Arial, \"Helvetica Neue\", sans-serif;\n      background: var(--bg);\n      color: var(--ink);\n      line-height: 1.6;\n    }\n\n    .hero {\n      min-height: 74vh;\n      display: flex;\n      align-items: center;\n      padding: 48px 24px 92px;\n      color: #fff;\n      background:\n        linear-gradient(90deg, rgba(15, 73, 53, .96), rgba(23, 107, 77, .84)),\n        url(\"https://images.unsplash.com/photo-1589924691995-400dc9ecc119?auto=format&fit=crop&w=1800&q=80\");\n      background-size: cover;\n      background-position: center;\n    }\n\n    .hero-inner,\n    .wrap {\n      width: min(1080px, calc(100% - 32px));\n      margin: 0 auto;\n    }\n\n    .eyebrow {\n      display: inline-flex;\n      align-items: center;\n      gap: 9px;\n      padding: 8px 12px;\n      border: 1px solid rgba(255, 255, 255, .35);\n      border-radius: 999px;\n      background: rgba(255, 255, 255, .12);\n      font-weight: 700;\n    }\n\n    h1,\n    h2,\n    h3,\n    p {\n      margin-top: 0;\n    }\n\n    h1 {\n      max-width: 780px;\n      margin: 22px 0 16px;\n      font-size: 58px;\n      line-height: 1.08;\n      letter-spacing: 0;\n    }\n\n    .hero p {\n      max-width: 760px;\n      margin-bottom: 0;\n      color: rgba(255, 255, 255, .88);\n      font-size: 22px;\n    }\n\n    .proposal-meta {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 10px;\n      max-width: 820px;\n      margin-top: 28px;\n    }\n\n    .meta-item {\n      padding: 12px 14px;\n      border: 1px solid rgba(255, 255, 255, .28);\n      border-radius: 8px;\n      background: rgba(255, 255, 255, .12);\n    }\n\n    .meta-item span {\n      display: block;\n      color: rgba(255, 255, 255, .72);\n      font-size: 13px;\n    }\n\n    .meta-item strong {\n      display: block;\n      margin-top: 3px;\n      color: #fff;\n    }\n\n    .summary-strip {\n      margin-top: -52px;\n      position: relative;\n      z-index: 2;\n    }\n\n    .summary-grid {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 12px;\n    }\n\n    .summary-item,\n    .panel,\n    .scope-item,\n    .phase,\n    .risk {\n      background: var(--paper);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      box-shadow: 0 16px 42px rgba(34, 48, 42, .07);\n    }\n\n    .summary-item {\n      min-height: 118px;\n      padding: 18px;\n    }\n\n    .summary-item strong {\n      display: block;\n      margin-bottom: 8px;\n      color: var(--green-2);\n      font-size: 26px;\n      line-height: 1.2;\n    }\n\n    .summary-item span,\n    p,\n    li {\n      color: var(--muted);\n    }\n\n    section {\n      padding: 58px 0;\n    }\n\n    .section-head {\n      margin-bottom: 20px;\n    }\n\n    .section-head span {\n      color: var(--gold);\n      font-weight: 800;\n    }\n\n    h2 {\n      margin-bottom: 8px;\n      font-size: 34px;\n      line-height: 1.2;\n      letter-spacing: 0;\n    }\n\n    h3 {\n      margin-bottom: 10px;\n      font-size: 21px;\n      line-height: 1.25;\n    }\n\n    .grid-2,\n    .grid-3 {\n      display: grid;\n      gap: 14px;\n    }\n\n    .grid-2 {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n\n    .grid-3 {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n    }\n\n    .panel,\n    .scope-item,\n    .phase,\n    .risk {\n      padding: 20px;\n    }\n\n    .panel.accent {\n      background: var(--soft);\n      border-color: #c9d9d1;\n    }\n\n    ul,\n    ol {\n      margin: 0;\n      padding: 0 20px 0 0;\n    }\n\n    li {\n      margin: 8px 0;\n    }\n\n    .tag {\n      display: inline-flex;\n      margin: 0 0 12px;\n      padding: 5px 9px;\n      border-radius: 999px;\n      background: #e7f0eb;\n      color: var(--green-2);\n      font-size: 13px;\n      font-weight: 700;\n    }\n\n    .scope-list {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 12px;\n    }\n\n    .scope-item {\n      min-height: 132px;\n    }\n\n    .scope-item strong {\n      display: block;\n      margin-bottom: 7px;\n      font-size: 18px;\n    }\n\n    .timeline {\n      display: grid;\n      gap: 12px;\n      counter-reset: phase;\n    }\n\n    .phase {\n      display: grid;\n      grid-template-columns: 58px 1fr;\n      gap: 14px;\n      align-items: start;\n    }\n\n    .phase::before {\n      counter-increment: phase;\n      content: counter(phase);\n      display: grid;\n      place-items: center;\n      width: 42px;\n      height: 42px;\n      border-radius: 999px;\n      background: var(--green);\n      color: #fff;\n      font-weight: 800;\n    }\n\n    .risk {\n      background: var(--warn);\n      border-color: #ecd7a7;\n    }\n\n    .placeholder {\n      display: grid;\n      gap: 10px;\n    }\n\n    .placeholder-row {\n      display: grid;\n      grid-template-columns: 180px 1fr;\n      gap: 12px;\n      align-items: center;\n      padding: 12px 0;\n      border-bottom: 1px solid var(--line);\n    }\n\n    .placeholder-row:last-child {\n      border-bottom: 0;\n    }\n\n    .placeholder-row strong {\n      color: var(--green-2);\n    }\n\n    .blank {\n      min-height: 36px;\n      border: 1px dashed #b9c6bf;\n      border-radius: 7px;\n      background: #fafcfb;\n    }\n\n    .signature-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 14px;\n    }\n\n    label {\n      display: block;\n      margin-bottom: 6px;\n      color: var(--green-2);\n      font-weight: 700;\n    }\n\n    input,\n    textarea {\n      width: 100%;\n      border: 1px solid #cbd8d1;\n      border-radius: 7px;\n      padding: 11px 12px;\n      font: inherit;\n      background: #fff;\n      color: var(--ink);\n    }\n\n    textarea {\n      min-height: 84px;\n      resize: vertical;\n    }\n\n    .field {\n      margin-bottom: 14px;\n    }\n\n    .signature-pad {\n      width: 100%;\n      height: 170px;\n      border: 1px dashed #9fb4aa;\n      border-radius: 8px;\n      background: #fff;\n      touch-action: none;\n    }\n\n    .checkbox-row {\n      display: flex;\n      align-items: flex-start;\n      gap: 9px;\n      margin: 12px 0 16px;\n      color: var(--muted);\n    }\n\n    .checkbox-row input {\n      width: auto;\n      margin-top: 5px;\n    }\n\n    .buttons {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 10px;\n    }\n\n    button {\n      border: 0;\n      border-radius: 7px;\n      padding: 11px 15px;\n      font: inherit;\n      font-weight: 700;\n      cursor: pointer;\n    }\n\n    .primary {\n      background: var(--green);\n      color: #fff;\n    }\n\n    .secondary {\n      background: #e4ece8;\n      color: var(--ink);\n    }\n\n    .notice {\n      display: none;\n      margin-top: 12px;\n      color: var(--green-2);\n      font-weight: 700;\n    }\n\n    .footer {\n      padding: 34px 0 46px;\n      color: var(--muted);\n      font-size: 14px;\n      text-align: center;\n    }\n\n    @media print {\n      body {\n        background: #fff;\n      }\n\n      .hero {\n        min-height: auto;\n        padding: 36px 24px;\n      }\n\n      .summary-strip {\n        margin-top: 0;\n      }\n\n      .summary-item,\n      .panel,\n      .scope-item,\n      .phase,\n      .risk {\n        box-shadow: none;\n      }\n    }\n\n    @media (max-width: 820px) {\n      .hero {\n        min-height: 66vh;\n        padding: 36px 18px 78px;\n      }\n\n      .hero-inner,\n      .wrap {\n        width: min(100% - 24px, 1080px);\n      }\n\n      h1 {\n        font-size: 40px;\n      }\n\n      .hero p {\n        font-size: 18px;\n      }\n\n      .summary-grid,\n      .grid-2,\n      .grid-3,\n      .scope-list,\n      .proposal-meta,\n      .signature-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .placeholder-row {\n        grid-template-columns: 1fr;\n      }\n    }\n  </style>\n</head>\n<body>\n  <header class=\"hero\">\n    <div class=\"hero-inner\">\n      <div class=\"eyebrow\">הצעת MVP | דרייב דוג</div>\n      <h1>מערכת CRM והזמנות ללקוחות חוזרים</h1>\n      <p>מסמך הצגת MVP למערכת שתאגד לקוחות, קטלוג מוצרים, מחירים אישיים, הזמנות, תשלומים, חשבוניות ומשלוחים במקום אחד.</p>\n      <div class=\"proposal-meta\">\n        <div class=\"meta-item\"><span>לכבוד</span><strong>דרייב דוג</strong></div>\n        <div class=\"meta-item\"><span>מגיש ההצעה</span><strong>Orma AI</strong></div>\n        <div class=\"meta-item\"><span>קישור</span><strong>proposals.orma-ai.com</strong></div>\n      </div>\n    </div>\n  </header>\n\n  <main>\n    <div class=\"summary-strip\">\n      <div class=\"wrap summary-grid\">\n        <div class=\"summary-item\">\n          <strong>~100</strong>\n          <span>לקוחות קיימים בתחילת הדרך</span>\n        </div>\n        <div class=\"summary-item\">\n          <strong>5-10</strong>\n          <span>הזמנות בתקופת פעילות טיפוסית</span>\n        </div>\n        <div class=\"summary-item\">\n          <strong>30-40</strong>\n          <span>מוצרים בקטלוג הראשוני</span>\n        </div>\n        <div class=\"summary-item\">\n          <strong>2 ימים</strong>\n          <span>התראה מינימלית לפני אספקה</span>\n        </div>\n      </div>\n    </div>\n\n    <section>\n      <div class=\"wrap grid-2\">\n        <article class=\"panel accent\">\n          <span class=\"tag\">מטרת הפרויקט</span>\n          <h2>לעשות סדר בתהליך המכירה והאספקה</h2>\n          <p>המערכת נועדה להחליף עבודה מפוזרת בוואטסאפ ובטלפון במרכז ניהולי אחד, שבו בעל העסק רואה לקוחות, הזמנות, תשלומים, חשבוניות ומשלוחים בצורה מהירה וברורה.</p>\n        </article>\n        <article class=\"panel\">\n          <span class=\"tag\">קהל יעד</span>\n          <h2>לקוחות קיימים, לא חנות פתוחה לציבור</h2>\n          <p>הלקוח לא נרשם לבד. בעל העסק מכניס אותו למערכת, ולאחר מכן הלקוח יכול להיכנס עם מספר טלפון וסיסמה כדי לבצע הזמנה חוזרת או לבחור מוצרים מהקטלוג. בכניסה הראשונה הלקוח מחליף את הסיסמה הראשונית.</p>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"wrap\">\n        <div class=\"section-head\">\n          <span>01</span>\n          <h2>מה כלול ב-MVP</h2>\n          <p>גרסה ראשונה ממוקדת שמאפשרת שימוש אמיתי בעסק בלי לבנות מערכת כבדה מדי.</p>\n        </div>\n        <div class=\"scope-list\">\n          <div class=\"scope-item\"><strong>ניהול לקוחות</strong><span>שם, טלפון, כתובת, אזור, הערות, היסטוריית הזמנות ומחירים אישיים.</span></div>\n          <div class=\"scope-item\"><strong>קטלוג מוצרים</strong><span>מותג, סדרה, סוג, טעם, משקל, מחיר בסיס ותמונה.</span></div>\n          <div class=\"scope-item\"><strong>מחירים והנחות</strong><span>מחיר קבוע ללקוח, הנחות ומבצעים פשוטים.</span></div>\n          <div class=\"scope-item\"><strong>פורטל לקוח</strong><span>כניסה עם טלפון וסיסמה, החלפת סיסמה ראשונית, צפייה בקטלוג והזמנה עצמאית.</span></div>\n          <div class=\"scope-item\"><strong>הזמנה חוזרת</strong><span>אפשרות מהירה להזמין שוב את המוצר האחרון שנרכש.</span></div>\n          <div class=\"scope-item\"><strong>עגלה והזמנה</strong><span>תמיכה בכמה מוצרים באותה הזמנה, כתובת, הערות ומועד אספקה.</span></div>\n          <div class=\"scope-item\"><strong>הזמנה ידנית</strong><span>בעל העסק יכול לפתוח הזמנה עבור לקוחות מבוגרים או הזמנות טלפוניות.</span></div>\n          <div class=\"scope-item\"><strong>תשלומים וחשבוניות</strong><span>קישור תשלום דרך משולם/Grow, קליטת סטטוס תשלום וחשבונית אונליין.</span></div>\n          <div class=\"scope-item\"><strong>מזומן לשליח</strong><span>אפשרות חריגה לתשלום מזומן, עם סימון ידני של סטטוס תשלום.</span></div>\n          <div class=\"scope-item\"><strong>מסך משלוחים</strong><span>רשימת הזמנות לפי תאריך, אזור וסטטוס תשלום.</span></div>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"wrap grid-2\">\n        <article class=\"panel\">\n          <div class=\"section-head\">\n            <span>02</span>\n            <h2>זרימת לקוח</h2>\n          </div>\n          <ol>\n            <li>נכנס לעמוד ההזמנות.</li>\n            <li>מזין טלפון וסיסמה.</li>\n            <li>בכניסה ראשונה מחליף את הסיסמה הראשונית.</li>\n            <li>רואה קטלוג ומוצר אחרון שנרכש.</li>\n            <li>בוחר מוצרים וכמויות.</li>\n            <li>מאשר כתובת ומוסיף הערות.</li>\n            <li>בוחר תשלום אונליין או מזומן לשליח.</li>\n            <li>הזמנה נכנסת למערכת לניהול בעל העסק.</li>\n          </ol>\n        </article>\n        <article class=\"panel\">\n          <div class=\"section-head\">\n            <span>03</span>\n            <h2>זרימת בעל העסק</h2>\n          </div>\n          <ol>\n            <li>מוסיף לקוחות ומוצרים.</li>\n            <li>מגדיר מחירים אישיים והנחות.</li>\n            <li>פותח הזמנה ידנית כשצריך.</li>\n            <li>יוצר קישור תשלום ושולח ללקוח.</li>\n            <li>רואה תשלומים וחשבוניות.</li>\n            <li>מנהל משלוחים לפי אזור ותאריך.</li>\n          </ol>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"wrap grid-2\">\n        <article class=\"panel accent\">\n          <div class=\"section-head\">\n            <span>04</span>\n            <h2>אינטגרציית משולם / Grow</h2>\n          </div>\n          <ul>\n            <li>יצירת קישור תשלום להזמנה.</li>\n            <li>העברת הלקוח לעמוד תשלום של Grow.</li>\n            <li>קליטת סטטוס תשלום דרך callback / webhook.</li>\n            <li>שמירת מספר חשבונית וקישור חשבונית כאשר Grow מחזירה אותם.</li>\n            <li>אין שמירת פרטי אשראי במערכת.</li>\n          </ul>\n        </article>\n        <article class=\"risk\">\n          <div class=\"section-head\">\n            <span>סיכון פתוח</span>\n            <h2>חשבונית על מזומן לשליח</h2>\n          </div>\n          <p>תשלום אונליין דרך Grow מתאים ל-MVP. לגבי תשלום מזומן לשליח, צריך אישור טכני מ-Grow האם ניתן להפיק חשבונית מס/קבלה דרך API עבור עסקה שלא שולמה אונליין.</p>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"wrap\">\n        <div class=\"section-head\">\n          <span>05</span>\n          <h2>תהליך עבודה מוצע</h2>\n        </div>\n        <div class=\"timeline\">\n          <div class=\"phase\">\n            <div>\n              <h3>אפיון סופי ומפת מסכים</h3>\n              <p>סגירת זרימות, סטטוסים, מסכים והתנהגות מרכזית לפני פיתוח.</p>\n            </div>\n          </div>\n          <div class=\"phase\">\n            <div>\n              <h3>עיצוב ופיתוח בסיס ניהולי</h3>\n              <p>לקוחות, מוצרים, מחירים, הזמנות ידניות ודשבורד ניהולי.</p>\n            </div>\n          </div>\n          <div class=\"phase\">\n            <div>\n              <h3>פורטל לקוח</h3>\n              <p>כניסה עם קוד, קטלוג, עגלה, כתובת, הערות והזמנה חוזרת.</p>\n            </div>\n          </div>\n          <div class=\"phase\">\n            <div>\n              <h3>חיבור משולם / Grow</h3>\n              <p>קישור תשלום, webhook, סטטוס תשלום וחשבונית אונליין.</p>\n            </div>\n          </div>\n          <div class=\"phase\">\n            <div>\n              <h3>בדיקות ועלייה לשימוש</h3>\n              <p>בדיקות מובייל, תרחישי תשלום, הזמנות ידניות, משלוחים ותיקונים אחרונים.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"wrap grid-2\">\n        <article class=\"panel\">\n          <div class=\"section-head\">\n            <span>06</span>\n            <h2>הנחות עבודה</h2>\n          </div>\n          <ul>\n            <li>בעל העסק מזין לקוחות למערכת.</li>\n            <li>הלקוחות לא נרשמים לבד.</li>\n            <li>התשלום הרצוי הוא בזמן ההזמנה.</li>\n            <li>מזומן לשליח הוא חריג, לא ברירת מחדל.</li>\n            <li>המערכת צריכה לעבוד טוב גם במובייל וגם במחשב.</li>\n            <li>משלוחים מנוהלים ידנית לפי תאריך ואזור.</li>\n            <li>תחזוקה חודשית לאחר העלייה לאוויר: 300 ₪ + מע״מ לחודש.</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <section>\n      <div class=\"wrap\">\n        <div class=\"section-head\">\n          <span>07</span>\n          <h2>אישור וחתימה דיגיטלית</h2>\n          <p>לאישור ההצעה, ניתן למלא פרטים ולחתום בתיבה. בלחיצה על אישור נוצר קובץ אישור חתום ונפתח מייל מוכן לשליחה ל-Orma AI.</p>\n        </div>\n        <div class=\"panel\">\n          <div class=\"signature-grid\">\n            <div>\n              <div class=\"field\">\n                <label for=\"signName\">שם מלא</label>\n                <input id=\"signName\" autocomplete=\"name\">\n              </div>\n              <div class=\"field\">\n                <label for=\"signPhone\">טלפון</label>\n                <input id=\"signPhone\" autocomplete=\"tel\">\n              </div>\n              <div class=\"field\">\n                <label for=\"signEmail\">אימייל</label>\n                <input id=\"signEmail\" autocomplete=\"email\">\n              </div>\n              <div class=\"field\">\n                <label for=\"signNotes\">הערות</label>\n                <textarea id=\"signNotes\"></textarea>\n              </div>\n            </div>\n            <div>\n              <label for=\"signaturePad\">חתימה</label>\n              <canvas id=\"signaturePad\" class=\"signature-pad\"></canvas>\n              <label class=\"checkbox-row\">\n                <input id=\"signApproval\" type=\"checkbox\">\n                <span>אני מאשר את ההצעה, תכולת ה-MVP, תנאי העבודה והעלות החודשית של 300 ₪ + מע״מ כמפורט במסמך זה.</span>\n              </label>\n              <div class=\"buttons\">\n                <button class=\"primary\" type=\"button\" id=\"downloadApproval\">אישור ושליחת חתימה</button>\n                <button class=\"secondary\" type=\"button\" id=\"clearSignature\">ניקוי חתימה</button>\n                <button class=\"secondary\" type=\"button\" id=\"printProposal\">הדפסה / PDF</button>\n              </div>\n              <div class=\"notice\" id=\"signatureNotice\">נוצר קובץ אישור חתום ונפתח מייל ל־Ami@hai.tech. יש לצרף את הקובץ למייל ולשלוח.</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"footer\">\n    Orma AI | פתרונות AI, אוטומציה ומערכות ניהול | proposals.orma-ai.com\n  </footer>\n  <script>\n    const canvas = document.getElementById('signaturePad');\n    const ctx = canvas.getContext('2d');\n    let drawing = false;\n\n    function resizeCanvas() {\n      const rect = canvas.getBoundingClientRect();\n      const image = canvas.toDataURL();\n      canvas.width = Math.max(1, Math.floor(rect.width * window.devicePixelRatio));\n      canvas.height = Math.max(1, Math.floor(rect.height * window.devicePixelRatio));\n      ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);\n      ctx.lineWidth = 2.3;\n      ctx.lineCap = 'round';\n      ctx.strokeStyle = '#14211c';\n      if (image) {\n        const img = new Image();\n        img.onload = () => ctx.drawImage(img, 0, 0, rect.width, rect.height);\n        img.src = image;\n      }\n    }\n\n    function point(event) {\n      const rect = canvas.getBoundingClientRect();\n      const touch = event.touches ? event.touches[0] : event;\n      return {\n        x: touch.clientX - rect.left,\n        y: touch.clientY - rect.top\n      };\n    }\n\n    function start(event) {\n      drawing = true;\n      const p = point(event);\n      ctx.beginPath();\n      ctx.moveTo(p.x, p.y);\n      event.preventDefault();\n    }\n\n    function draw(event) {\n      if (!drawing) return;\n      const p = point(event);\n      ctx.lineTo(p.x, p.y);\n      ctx.stroke();\n      event.preventDefault();\n    }\n\n    function stop() {\n      drawing = false;\n    }\n\n    function fieldValue(id) {\n      return document.getElementById(id).value.trim();\n    }\n\n    function signatureIsBlank() {\n      const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;\n      for (let i = 3; i < pixels.length; i += 4) {\n        if (pixels[i] !== 0) return false;\n      }\n      return true;\n    }\n\n    function downloadSignedApproval() {\n      const approved = document.getElementById('signApproval').checked;\n      const name = fieldValue('signName');\n      if (!approved || !name || signatureIsBlank()) {\n        alert('צריך למלא שם, לסמן אישור ולחתום לפני שליחה.');\n        return;\n      }\n\n      const signature = canvas.toDataURL('image/png');\n      const date = new Date().toLocaleString('he-IL');\n      const html = `<!doctype html><html lang=\"he\" dir=\"rtl\"><meta charset=\"utf-8\"><title>אישור הצעת MVP - דרייב דוג</title><body style=\"font-family:Arial,sans-serif;line-height:1.6;padding:32px;max-width:760px;margin:auto\"><h1>אישור הצעת MVP - דרייב דוג</h1><p><strong>תאריך אישור:</strong> ${date}</p><p><strong>שם מלא:</strong> ${fieldValue('signName')}</p><p><strong>טלפון:</strong> ${fieldValue('signPhone')}</p><p><strong>אימייל:</strong> ${fieldValue('signEmail')}</p><p><strong>הערות:</strong><br>${fieldValue('signNotes').replaceAll('\\n', '<br>')}</p><p>אני מאשר את ההצעה, תכולת ה-MVP, תנאי העבודה והעלות החודשית של 300 ₪ + מע״מ כמפורט במסמך.</p><h2>חתימה</h2><img src=\"${signature}\" style=\"border:1px solid #ccc;max-width:420px;width:100%\"><footer style=\"margin-top:32px;color:#667\">Orma AI | proposals.orma-ai.com</footer></body></html>`;\n      const blob = new Blob([html], { type: 'text/html;charset=utf-8' });\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement('a');\n      link.href = url;\n      link.download = 'drive-dog-mvp-signed-approval.html';\n      document.body.appendChild(link);\n      link.click();\n      link.remove();\n      URL.revokeObjectURL(url);\n      document.getElementById('signatureNotice').style.display = 'block';\n\n      const subject = encodeURIComponent('אישור הצעת MVP - דרייב דוג');\n      const body = encodeURIComponent([\n        'שלום,',\n        '',\n        'מצורף אישור חתום להצעת MVP - דרייב דוג.',\n        '',\n        `שם: ${fieldValue('signName')}`,\n        `טלפון: ${fieldValue('signPhone')}`,\n        `אימייל: ${fieldValue('signEmail')}`,\n        `תאריך אישור: ${date}`,\n        '',\n        'הערות:',\n        fieldValue('signNotes') || '-',\n        '',\n        'יש לצרף למייל את קובץ האישור החתום שירד למחשב/טלפון.'\n      ].join('\\n'));\n      window.location.href = `mailto:Ami@hai.tech?subject=${subject}&body=${body}`;\n    }\n\n    window.addEventListener('resize', resizeCanvas);\n    resizeCanvas();\n    canvas.addEventListener('mousedown', start);\n    canvas.addEventListener('mousemove', draw);\n    window.addEventListener('mouseup', stop);\n    canvas.addEventListener('touchstart', start, { passive: false });\n    canvas.addEventListener('touchmove', draw, { passive: false });\n    window.addEventListener('touchend', stop);\n    document.getElementById('clearSignature').addEventListener('click', () => {\n      ctx.clearRect(0, 0, canvas.width, canvas.height);\n    });\n    document.getElementById('printProposal').addEventListener('click', () => window.print());\n    document.getElementById('downloadApproval').addEventListener('click', downloadSignedApproval);\n  </script>\n</body>\n</html>\n";
const adminHtml = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Drive Dog | ניהול</title>\n  <link rel=\"icon\" href=\"/assets/drive-dog-logo.jpg\">\n  <style>\n    :root {\n      color-scheme: light;\n      --bg: #fff7ed;\n      --panel: #fffdfa;\n      --panel-2: #fff1dc;\n      --ink: #351704;\n      --muted: #76583d;\n      --line: #ead6bc;\n      --brand: #f49b25;\n      --brand-dark: #7a3507;\n      --brand-ink: #4f2306;\n      --brand-soft: #ffe0ac;\n      --sidebar: #592700;\n      --warn: #a95f00;\n      --danger: #a83220;\n      --ok: #3f7b35;\n      --shadow: 0 12px 30px rgba(89, 39, 0, 0.10);\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      font-family: Arial, \"Helvetica Neue\", sans-serif;\n      background:\n        linear-gradient(180deg, #fff7ed 0%, #f9eddd 100%);\n      color: var(--ink);\n      line-height: 1.45;\n    }\n\n    button,\n    input,\n    select,\n    textarea {\n      font: inherit;\n    }\n\n    button {\n      border: 0;\n      cursor: pointer;\n    }\n\n    .app {\n      min-height: 100vh;\n      display: grid;\n      grid-template-columns: 250px 1fr;\n    }\n\n    .menu-toggle,\n    .sidebar-backdrop {\n      display: none;\n    }\n\n    .sidebar {\n      position: sticky;\n      top: 0;\n      height: 100vh;\n      padding: 18px;\n      background: var(--sidebar);\n      color: #ffffff;\n      display: flex;\n      flex-direction: column;\n      gap: 18px;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      min-height: 64px;\n      font-weight: 800;\n      font-size: 18px;\n      color: #ffe4bb;\n    }\n\n    .brand-logo {\n      width: 64px;\n      height: 64px;\n      flex: 0 0 auto;\n      border-radius: 8px;\n      object-fit: cover;\n      background: #fff7ed;\n      border: 2px solid rgba(255, 224, 172, 0.72);\n      box-shadow: 0 8px 18px rgba(53, 23, 4, 0.26);\n    }\n\n    .brand-name {\n      display: grid;\n      gap: 2px;\n      line-height: 1.05;\n    }\n\n    .brand-name strong {\n      color: #fff7ed;\n      font-size: 18px;\n    }\n\n    .brand-name span {\n      color: rgba(255, 244, 229, 0.72);\n      font-size: 12px;\n      font-weight: 700;\n    }\n\n    .sidebar-close {\n      display: none;\n      margin-inline-start: auto;\n      width: 36px;\n      height: 36px;\n      border-radius: 7px;\n      background: rgba(255, 255, 255, 0.12);\n      color: #ffffff;\n      font-size: 22px;\n      line-height: 1;\n    }\n\n    nav {\n      display: grid;\n      gap: 8px;\n    }\n\n    .nav-button {\n      min-height: 42px;\n      padding: 10px 12px;\n      border-radius: 7px;\n      text-align: right;\n      color: rgba(255, 244, 229, 0.78);\n      background: transparent;\n      border: 1px solid transparent;\n    }\n\n    .nav-button.active,\n    .nav-button:hover {\n      color: #ffffff;\n      background: rgba(244, 155, 37, 0.22);\n      border-color: rgba(255, 224, 172, 0.22);\n    }\n\n    .side-note {\n      margin-top: auto;\n      padding: 12px;\n      border: 1px solid rgba(255, 224, 172, 0.22);\n      border-radius: 8px;\n      color: rgba(255, 244, 229, 0.76);\n      font-size: 13px;\n    }\n\n    main {\n      padding: 22px;\n      min-width: 0;\n    }\n\n    .topbar {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 16px;\n      margin-bottom: 18px;\n    }\n\n    .page-heading {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      min-width: 0;\n    }\n\n    .header-logo {\n      width: 56px;\n      height: 56px;\n      flex: 0 0 auto;\n      border-radius: 8px;\n      object-fit: cover;\n      background: #fff7ed;\n      border: 1px solid var(--line);\n      box-shadow: var(--shadow);\n    }\n\n    .page-title-copy {\n      min-width: 0;\n    }\n\n    h1 {\n      margin: 0 0 5px;\n      font-size: 25px;\n      letter-spacing: 0;\n    }\n\n    .subtitle {\n      margin: 0;\n      color: var(--muted);\n      font-size: 14px;\n    }\n\n    .toolbar {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      justify-content: flex-end;\n    }\n\n    .button {\n      min-height: 38px;\n      padding: 9px 12px;\n      border-radius: 7px;\n      background: var(--brand-soft);\n      color: var(--ink);\n      font-weight: 700;\n      white-space: nowrap;\n    }\n\n    .button.primary {\n      background: var(--brand);\n      color: var(--brand-ink);\n      box-shadow: inset 0 -2px 0 rgba(53, 23, 4, 0.16);\n    }\n\n    .button.primary:hover {\n      background: var(--brand-dark);\n      color: #ffffff;\n    }\n    .button.danger { color: #ffffff; background: var(--danger); }\n    .button.ghost { background: transparent; border: 1px solid var(--line); }\n    .button.ghost:hover,\n    .mini:hover {\n      border-color: #d69b59;\n      background: #fff1dc;\n    }\n\n    .grid {\n      display: grid;\n      gap: 14px;\n    }\n\n    .metrics {\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      margin-bottom: 14px;\n    }\n\n    .metric,\n    .panel {\n      background: var(--panel);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      box-shadow: var(--shadow);\n    }\n\n    .metric {\n      padding: 15px;\n      min-height: 96px;\n    }\n\n    .metric span {\n      color: var(--muted);\n      font-size: 13px;\n    }\n\n    .metric strong {\n      display: block;\n      margin-top: 8px;\n      font-size: 28px;\n    }\n\n    .panel {\n      padding: 16px;\n      overflow: hidden;\n    }\n\n    .panel-head {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n      margin-bottom: 12px;\n    }\n\n    h2 {\n      margin: 0;\n      font-size: 18px;\n      letter-spacing: 0;\n    }\n\n    .split {\n      display: grid;\n      grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);\n      gap: 14px;\n      align-items: start;\n    }\n\n    .form-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .field.full { grid-column: 1 / -1; }\n\n    label {\n      display: block;\n      margin-bottom: 5px;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 700;\n    }\n\n    input,\n    select,\n    textarea {\n      width: 100%;\n      border: 1px solid #dfc6aa;\n      border-radius: 7px;\n      padding: 9px 10px;\n      background: #ffffff;\n      color: var(--ink);\n    }\n\n    a {\n      color: #8a3f08;\n      font-weight: 700;\n    }\n\n    input:focus,\n    select:focus,\n    textarea:focus {\n      outline: 3px solid rgba(244, 155, 37, 0.22);\n      border-color: #d87510;\n    }\n\n    textarea {\n      min-height: 76px;\n      resize: vertical;\n    }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      min-width: 760px;\n    }\n\n    th,\n    td {\n      padding: 10px 8px;\n      border-bottom: 1px solid var(--line);\n      text-align: right;\n      vertical-align: top;\n      font-size: 14px;\n    }\n\n    th {\n      color: var(--muted);\n      font-size: 12px;\n      background: var(--panel-2);\n      position: sticky;\n      top: 0;\n      z-index: 1;\n    }\n\n    .table-wrap {\n      overflow-x: auto;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n    }\n\n    .row-actions {\n      display: flex;\n      gap: 6px;\n      flex-wrap: wrap;\n    }\n\n    .mini {\n      min-height: 30px;\n      padding: 6px 9px;\n      border-radius: 6px;\n      border: 1px solid transparent;\n      background: #fff1dc;\n      color: var(--ink);\n      font-weight: 700;\n      font-size: 12px;\n    }\n\n    .mini.danger {\n      background: #fde8e6;\n      color: var(--danger);\n    }\n\n    .status {\n      display: inline-flex;\n      align-items: center;\n      min-height: 26px;\n      padding: 4px 8px;\n      border-radius: 999px;\n      background: #fff1dc;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 700;\n      white-space: nowrap;\n    }\n\n    .status.ok { background: #e9f4df; color: var(--ok); }\n    .status.warn { background: #ffe4b6; color: var(--warn); }\n    .status.danger { background: #fde8e6; color: var(--danger); }\n\n    .filters {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 10px;\n      margin-bottom: 12px;\n    }\n\n    .order-builder {\n      display: grid;\n      gap: 10px;\n    }\n\n    .item-row {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) 82px 42px;\n      gap: 8px;\n      align-items: end;\n    }\n\n    .total-line {\n      display: flex;\n      justify-content: space-between;\n      gap: 12px;\n      padding-top: 8px;\n      border-top: 1px solid var(--line);\n      font-weight: 800;\n      font-size: 18px;\n    }\n\n    .list {\n      display: grid;\n      gap: 10px;\n    }\n\n    .delivery-card {\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fffdfa;\n      overflow-wrap: anywhere;\n    }\n\n    .delivery-card.cash {\n      border-color: #eca041;\n      background: #fff1dc;\n    }\n\n    .muted { color: var(--muted); }\n    .nowrap { white-space: nowrap; }\n    .hidden { display: none !important; }\n    .break-word { overflow-wrap: anywhere; }\n\n    .profile-grid {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) minmax(280px, 0.45fr);\n      gap: 14px;\n      align-items: start;\n    }\n\n    .profile-stack {\n      display: grid;\n      gap: 14px;\n    }\n\n    .detail-list {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .detail-list div {\n      padding: 10px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #ffffff;\n      overflow-wrap: anywhere;\n    }\n\n    .detail-list span {\n      display: block;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 700;\n    }\n\n    .modal-backdrop {\n      position: fixed;\n      inset: 0;\n      display: grid;\n      place-items: center;\n      padding: 18px;\n      background: rgba(53, 23, 4, 0.48);\n      z-index: 20;\n    }\n\n    .modal {\n      width: min(560px, 100%);\n      max-height: calc(100vh - 36px);\n      overflow: auto;\n      padding: 16px;\n      border-radius: 8px;\n      background: var(--panel);\n      box-shadow: var(--shadow);\n    }\n\n    .empty {\n      padding: 22px;\n      text-align: center;\n      color: var(--muted);\n      background: var(--panel-2);\n      border: 1px dashed var(--line);\n      border-radius: 8px;\n    }\n\n    .toast {\n      position: fixed;\n      left: 18px;\n      bottom: 18px;\n      max-width: min(420px, calc(100% - 36px));\n      padding: 12px 14px;\n      border-radius: 8px;\n      background: var(--sidebar);\n      color: #ffffff;\n      box-shadow: var(--shadow);\n      z-index: 10;\n    }\n\n    @media (max-width: 960px) {\n      .app { grid-template-columns: 1fr; }\n      body.menu-open { overflow: hidden; }\n      .menu-toggle {\n        position: fixed;\n        top: 12px;\n        right: 12px;\n        z-index: 31;\n        display: grid;\n        place-items: center;\n        width: 44px;\n        height: 44px;\n        border-radius: 8px;\n        background: var(--brand);\n        color: var(--brand-ink);\n        box-shadow: var(--shadow);\n        font-size: 24px;\n        line-height: 1;\n      }\n      .sidebar-backdrop {\n        position: fixed;\n        inset: 0;\n        z-index: 29;\n        background: rgba(53, 23, 4, 0.46);\n      }\n      body.menu-open .sidebar-backdrop { display: block; }\n      .sidebar {\n        position: fixed;\n        top: 0;\n        right: 0;\n        bottom: 0;\n        z-index: 30;\n        width: min(82vw, 320px);\n        height: 100dvh;\n        transform: translateX(105%);\n        transition: transform 180ms ease;\n        box-shadow: -16px 0 34px rgba(53, 23, 4, 0.24);\n      }\n      body.menu-open .sidebar { transform: translateX(0); }\n      .brand-logo {\n        width: 58px;\n        height: 58px;\n      }\n      .sidebar-close { display: grid; place-items: center; }\n      nav {\n        grid-template-columns: 1fr;\n        overflow-y: auto;\n      }\n      .side-note { display: none; }\n      main { padding-top: 68px; }\n      .split,\n      .profile-grid,\n      .metrics,\n      .filters {\n        grid-template-columns: 1fr;\n      }\n      .topbar {\n        display: grid;\n      }\n      .page-heading {\n        padding-inline-start: 52px;\n      }\n      .toolbar {\n        justify-content: stretch;\n      }\n      .toolbar .button {\n        flex: 1;\n      }\n    }\n\n    @media (max-width: 620px) {\n      main { padding: 66px 14px 14px; }\n      .topbar { gap: 12px; }\n      .header-logo {\n        width: 48px;\n        height: 48px;\n      }\n      h1 { font-size: 22px; }\n      .form-grid,\n      .detail-list,\n      .item-row {\n        grid-template-columns: 1fr;\n      }\n      .item-row .mini {\n        min-height: 36px;\n      }\n    }\n  </style>\n</head>\n<body>\n  <button class=\"menu-toggle\" id=\"menuToggle\" type=\"button\" aria-label=\"פתיחת תפריט\" aria-controls=\"sidebar\" aria-expanded=\"false\">☰</button>\n  <div class=\"sidebar-backdrop\" id=\"sidebarBackdrop\"></div>\n  <div class=\"app\">\n    <aside class=\"sidebar\" id=\"sidebar\">\n      <div class=\"brand\">\n        <img class=\"brand-logo\" src=\"/assets/drive-dog-logo.jpg\" alt=\"Drive Dog\">\n        <span class=\"brand-name\"><strong>דרייב דוג</strong><span>Drive Dog</span></span>\n        <button class=\"sidebar-close\" id=\"sidebarClose\" type=\"button\" aria-label=\"סגירת תפריט\">×</button>\n      </div>\n      <nav id=\"nav\"></nav>\n      <div class=\"side-note\">MVP פנימי: הדאטה נשמר בדפדפן בלבד. Grow / משולם מסומן כ-stub ולא מחייב בפועל.</div>\n    </aside>\n    <main>\n      <div class=\"topbar\">\n        <div class=\"page-heading\">\n          <img class=\"header-logo\" src=\"/assets/drive-dog-logo.jpg\" alt=\"Drive Dog\">\n          <div class=\"page-title-copy\">\n            <h1 id=\"pageTitle\">דשבורד</h1>\n            <p id=\"pageSubtitle\" class=\"subtitle\">תמונת מצב קצרה על לקוחות, הזמנות ותשלומים.</p>\n          </div>\n        </div>\n      </div>\n      <section id=\"view\"></section>\n    </main>\n  </div>\n  <div class=\"toast hidden\" id=\"toast\"></div>\n  <div class=\"modal-backdrop hidden\" id=\"modalRoot\"></div>\n\n  <script>\n    const STORAGE_KEY = 'driveDogAdminMvpV1';\n    const tabs = [\n      ['dashboard', 'דשבורד', 'תמונת מצב קצרה על לקוחות, הזמנות ותשלומים.'],\n      ['customers', 'לקוחות', 'ניהול לקוחות קיימים בלבד. אין הרשמה פתוחה.'],\n      ['deletedCustomers', 'לקוחות מחוקים', 'ארכיון לקוחות שנמחקו מהמסך הראשי.'],\n      ['products', 'מוצרים', 'קטלוג בסיסי של משפחות ווריאנטים.'],\n      ['pricing', 'מחירים', 'מחיר אישי או הנחה לפי לקוח ומוצר.'],\n      ['orders', 'הזמנות', 'יצירת הזמנה ידנית וניהול סטטוס תשלום.'],\n      ['deliveries', 'משלוחים', 'רשימת אספקות לפי תאריך ואזור.'],\n      ['settings', 'הגדרות', 'תלויות חיצוניות שמסומנות כ-stub.']\n    ];\n\n    const seed = {\n      customers: [\n        { id: 'c1', name: 'עמי כהן', phone: '050-1111111', address: 'הכלנית 12', city: 'ראשון לציון', area: 'מרכז', deliveryNotes: 'להתקשר לפני הגעה', internalNotes: 'מעדיף שק 12 ק\"ג', active: true },\n        { id: 'c2', name: 'דנה לוי', phone: '052-2222222', address: 'הגפן 8', city: 'רחובות', area: 'שפלה', deliveryNotes: 'להשאיר ליד הדלת', internalNotes: 'משלמת אונליין', active: true },\n        { id: 'c3', name: 'יוסי מזרחי', phone: '054-3333333', address: 'העצמאות 40', city: 'אשדוד', area: 'דרום', deliveryNotes: 'כלב גדול בחצר', internalNotes: 'מזומן לשליח', active: true }\n      ],\n      products: [\n        { id: 'p1', brand: 'Brit', series: 'Care', animal: 'כלב', stage: 'בוגר', flavor: 'כבש ואורז', weightKg: 12, name: 'Brit Care כבש ואורז 12 ק\"ג', basePrice: 279, active: true },\n        { id: 'p2', brand: 'Monge', series: 'Natural', animal: 'כלב', stage: 'גור', flavor: 'עוף', weightKg: 12, name: 'Monge גור עוף 12 ק\"ג', basePrice: 295, active: true },\n        { id: 'p3', brand: 'Acana', series: 'Classic', animal: 'כלב', stage: 'בוגר', flavor: 'עוף', weightKg: 11.4, name: 'Acana Classic עוף 11.4 ק\"ג', basePrice: 349, active: true },\n        { id: 'p4', brand: 'Royal Canin', series: 'Indoor', animal: 'חתול', stage: 'בוגר', flavor: 'עוף', weightKg: 4, name: 'Royal Canin Indoor חתול 4 ק\"ג', basePrice: 189, active: true },\n        { id: 'p5', brand: 'Josera', series: 'SensiCat', animal: 'חתול', stage: 'בוגר', flavor: 'עוף', weightKg: 10, name: 'Josera SensiCat 10 ק\"ג', basePrice: 265, active: true }\n      ],\n      prices: [\n        { id: 'cp1', customerId: 'c1', productId: 'p1', customPrice: 259, discountPercent: 0, notes: 'מחיר קבוע' },\n        { id: 'cp2', customerId: 'c2', productId: 'p4', customPrice: 0, discountPercent: 8, notes: 'הנחת לקוחה קבועה' }\n      ],\n      invoices: [\n        { id: 'inv1', customerId: 'c1', invoiceNumber: 'DD-1001', date: '2026-07-22', amount: 259, paymentStatus: 'paid_online', link: 'https://pay.example.test/invoices/DD-1001' },\n        { id: 'inv2', customerId: 'c2', invoiceNumber: 'DD-1002', date: '2026-07-21', amount: 348, paymentStatus: 'paid_online', link: 'https://pay.example.test/invoices/DD-1002' }\n      ],\n      orders: [\n        { id: 'o1001', customerId: 'c1', createdAt: '2026-07-22', deliveryDate: '2026-07-25', status: 'new', paymentStatus: 'pending_online_payment', source: 'manual', paymentUrl: 'https://pay.example.test/orders/o1001', notes: 'לשלוח קישור תשלום', items: [{ productId: 'p1', quantity: 1, unitPrice: 259 }] },\n        { id: 'o1002', customerId: 'c2', createdAt: '2026-07-21', deliveryDate: '2026-07-24', status: 'confirmed', paymentStatus: 'paid_online', source: 'manual', paymentUrl: 'https://pay.example.test/orders/o1002', notes: '', items: [{ productId: 'p4', quantity: 2, unitPrice: 174 }] },\n        { id: 'o1003', customerId: 'c3', createdAt: '2026-07-20', deliveryDate: '2026-07-26', status: 'confirmed', paymentStatus: 'cash_on_delivery', source: 'manual', paymentUrl: '', notes: 'מזומן לשליח', items: [{ productId: 'p3', quantity: 1, unitPrice: 349 }] }\n      ],\n      selected: { customerId: 'c1', customerProfileId: 'c1', productId: 'p1' }\n    };\n\n    let state = loadState();\n    let currentTab = 'dashboard';\n    let customersLoadState = 'loading';\n    let customersLoadError = '';\n    let deletedCustomersLoadState = 'idle';\n    let deletedCustomersLoadError = '';\n    let deletedCustomers = [];\n    let customersSaving = false;\n\n    function clone(value) {\n      return JSON.parse(JSON.stringify(value));\n    }\n\n    function loadState() {\n      const raw = localStorage.getItem(STORAGE_KEY);\n      if (!raw) return clone(seed);\n      try {\n        return { ...clone(seed), ...JSON.parse(raw) };\n      } catch {\n        return clone(seed);\n      }\n    }\n\n    function saveState(message) {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n      if (message) toast(message);\n      render();\n    }\n\n    async function loadCustomersFromServer() {\n      customersLoadState = 'loading';\n      customersLoadError = '';\n      render();\n      try {\n        const response = await fetch('/api/customers');\n        const data = await response.json();\n        if (!response.ok) throw new Error(data.error || 'טעינת הלקוחות נכשלה');\n        state.customers = data.customers.map(normalizeCustomer);\n        customersLoadState = 'ready';\n      } catch (error) {\n        customersLoadState = 'error';\n        customersLoadError = error.message || 'טעינת הלקוחות נכשלה';\n      }\n      render();\n    }\n\n    async function loadDeletedCustomersFromServer() {\n      deletedCustomersLoadState = 'loading';\n      deletedCustomersLoadError = '';\n      render();\n      try {\n        const response = await fetch('/api/customers/deleted');\n        const data = await response.json();\n        if (!response.ok) throw new Error(data.error || 'טעינת ארכיון הלקוחות נכשלה');\n        deletedCustomers = data.customers.map(normalizeCustomer);\n        deletedCustomersLoadState = 'ready';\n      } catch (error) {\n        deletedCustomersLoadState = 'error';\n        deletedCustomersLoadError = error.message || 'טעינת ארכיון הלקוחות נכשלה';\n      }\n      render();\n    }\n\n    async function customerApi(path, options = {}) {\n      const response = await fetch(path, {\n        ...options,\n        headers: {\n          'content-type': 'application/json',\n          ...(options.headers || {})\n        }\n      });\n      const data = await response.json();\n      if (!response.ok) throw new Error(data.error || 'פעולת הלקוח נכשלה');\n      return data;\n    }\n\n    function normalizeCustomer(item) {\n      const firstName = item.firstName || String(item.name || '').trim().split(/\\s+/)[0] || '';\n      const lastName = item.lastName || String(item.name || '').trim().split(/\\s+/).slice(1).join(' ');\n      return {\n        ...item,\n        firstName,\n        lastName,\n        name: [firstName, lastName].filter(Boolean).join(' '),\n        active: item.active !== false\n      };\n    }\n\n    function shekel(value) {\n      return new Intl.NumberFormat('he-IL', { style: 'currency', currency: 'ILS', maximumFractionDigits: 0 }).format(value || 0);\n    }\n\n    function today() {\n      return new Date().toISOString().slice(0, 10);\n    }\n\n    function nextId(prefix, list) {\n      return prefix + (Date.now().toString(36) + list.length.toString(36));\n    }\n\n    function customer(id) {\n      return state.customers.find((item) => item.id === id);\n    }\n\n    function customerName(item) {\n      if (!item) return '-';\n      return [item.firstName, item.lastName].filter(Boolean).join(' ') || item.name || '-';\n    }\n\n    function product(id) {\n      return state.products.find((item) => item.id === id);\n    }\n\n    function orderTotal(order) {\n      return order.items.reduce((sum, item) => sum + Number(item.quantity || 0) * Number(item.unitPrice || 0), 0);\n    }\n\n    function customerMetrics(customerId) {\n      const orders = customerOrders(customerId);\n      const total = orders.reduce((sum, order) => sum + orderTotal(order), 0);\n      const lastOrderDate = orders.map((order) => order.createdAt || order.deliveryDate || '').sort().at(-1) || '';\n      return {\n        orderCount: orders.length,\n        total,\n        averageOrder: orders.length ? Math.round(total / orders.length) : 0,\n        lastOrderDate\n      };\n    }\n\n    function customerOrders(customerId) {\n      return state.orders.filter((order) => order.customerId === customerId);\n    }\n\n    function customerInvoices(customerId) {\n      return (state.invoices || []).filter((invoice) => invoice.customerId === customerId);\n    }\n\n    function customerPrices(customerId) {\n      return state.prices.filter((price) => price.customerId === customerId);\n    }\n\n    function priceFor(customerId, productId) {\n      const base = product(productId)?.basePrice || 0;\n      const override = state.prices.find((item) => item.customerId === customerId && item.productId === productId);\n      if (!override) return base;\n      const custom = Number(override.customPrice || 0);\n      const start = custom > 0 ? custom : base;\n      return Math.round(start * (1 - Number(override.discountPercent || 0) / 100));\n    }\n\n    function statusLabel(value) {\n      const labels = {\n        new: 'חדשה',\n        confirmed: 'מאושרת',\n        delivered: 'סופקה',\n        cancelled: 'בוטלה',\n        pending_online_payment: 'ממתין לתשלום',\n        cash_on_delivery: 'מזומן לשליח',\n        paid_cash: 'שולם במזומן',\n        paid_online: 'שולם אונליין',\n        failed: 'נכשל'\n      };\n      return labels[value] || value;\n    }\n\n    function statusClass(value) {\n      if (['paid_online', 'paid_cash', 'delivered', 'confirmed'].includes(value)) return 'ok';\n      if (['cash_on_delivery', 'pending_online_payment', 'new'].includes(value)) return 'warn';\n      if (['failed', 'cancelled'].includes(value)) return 'danger';\n      return '';\n    }\n\n    function toast(message) {\n      const node = document.getElementById('toast');\n      node.textContent = message;\n      node.classList.remove('hidden');\n      window.clearTimeout(toast.timer);\n      toast.timer = window.setTimeout(() => node.classList.add('hidden'), 2400);\n    }\n\n    function setMenuOpen(open) {\n      document.body.classList.toggle('menu-open', open);\n      document.getElementById('menuToggle').setAttribute('aria-expanded', String(open));\n    }\n\n    function bindShell() {\n      document.getElementById('menuToggle').addEventListener('click', () => setMenuOpen(!document.body.classList.contains('menu-open')));\n      document.getElementById('sidebarClose').addEventListener('click', () => setMenuOpen(false));\n      document.getElementById('sidebarBackdrop').addEventListener('click', () => setMenuOpen(false));\n      document.addEventListener('keydown', (event) => {\n        if (event.key === 'Escape') setMenuOpen(false);\n      });\n    }\n\n    function renderNav() {\n      const nav = document.getElementById('nav');\n      nav.innerHTML = tabs.map(([id, label]) => `<button class=\"nav-button ${id === currentTab ? 'active' : ''}\" data-tab=\"${id}\" type=\"button\">${label}</button>`).join('');\n      nav.querySelectorAll('button').forEach((button) => {\n        button.addEventListener('click', () => {\n          currentTab = button.dataset.tab;\n          setMenuOpen(false);\n          if (currentTab === 'deletedCustomers' && deletedCustomersLoadState === 'idle') loadDeletedCustomersFromServer();\n          render();\n        });\n      });\n    }\n\n    function render() {\n      renderNav();\n      const views = {\n        dashboard: dashboardView,\n        customers: customersView,\n        deletedCustomers: deletedCustomersView,\n        customerProfile: customerProfileView,\n        products: productsView,\n        pricing: pricingView,\n        orders: ordersView,\n        deliveries: deliveriesView,\n        settings: settingsView\n      };\n      const tabMeta = tabs.find(([id]) => id === currentTab);\n      const profileCustomer = customer(state.selected.customerProfileId);\n      const title = currentTab === 'customerProfile' ? customerName(profileCustomer) : tabMeta?.[1] || 'Drive Dog';\n      const subtitle = currentTab === 'customerProfile' ? 'פרופיל לקוח: פרטים, הזמנות, חשבוניות, מדדים ואיפוס סיסמה.' : tabMeta?.[2] || '';\n      document.getElementById('pageTitle').textContent = title;\n      document.getElementById('pageSubtitle').textContent = subtitle;\n      const view = document.getElementById('view');\n      view.innerHTML = views[currentTab]();\n      bindView();\n    }\n\n    function dashboardView() {\n      const openOrders = state.orders.filter((order) => order.status !== 'delivered' && order.status !== 'cancelled');\n      const cash = state.orders.filter((order) => order.paymentStatus === 'cash_on_delivery');\n      const revenue = state.orders.filter((order) => ['paid_online', 'paid_cash'].includes(order.paymentStatus)).reduce((sum, order) => sum + orderTotal(order), 0);\n      return `\n        <div class=\"grid metrics\">\n          <div class=\"metric\"><span>לקוחות</span><strong>${state.customers.filter((item) => !item.deletedAt).length}</strong></div>\n          <div class=\"metric\"><span>מוצרים פעילים</span><strong>${state.products.filter((item) => item.active).length}</strong></div>\n          <div class=\"metric\"><span>הזמנות פתוחות</span><strong>${openOrders.length}</strong></div>\n          <div class=\"metric\"><span>שולם בדמו</span><strong>${shekel(revenue)}</strong></div>\n        </div>\n        <div class=\"split\">\n          <div class=\"panel\">\n            <div class=\"panel-head\"><h2>הזמנות קרובות</h2><button class=\"button primary\" data-goto=\"orders\" type=\"button\">הזמנה חדשה</button></div>\n            ${ordersTable(state.orders.slice().sort((a, b) => (a.deliveryDate || '').localeCompare(b.deliveryDate || '')).slice(0, 6))}\n          </div>\n          <div class=\"panel\">\n            <div class=\"panel-head\"><h2>תשומת לב</h2></div>\n            <div class=\"list\">\n              <div class=\"delivery-card cash\"><strong>${cash.length} הזמנות מזומן לשליח</strong><br><span class=\"muted\">צריך לוודא גבייה וסימון ידני.</span></div>\n              <div class=\"delivery-card\"><strong>Grow / משולם עדיין stub</strong><br><span class=\"muted\">כפתור קישור תשלום יוצר URL בדיקה בלבד.</span></div>\n              <div class=\"delivery-card\"><strong>פורטל לקוח בשלב הבא</strong><br><span class=\"muted\">טלפון + סיסמה והחלפת סיסמה ראשונה כבר מוגדרים באפיון.</span></div>\n            </div>\n          </div>\n        </div>`;\n    }\n\n    function customersView() {\n      return `\n        <div class=\"split\">\n          <div class=\"panel\">\n            <div class=\"panel-head\"><h2>לקוחות</h2><input id=\"customerSearch\" placeholder=\"חיפוש לפי שם, כתובת, טלפון או עיר\"></div>\n            <div class=\"table-wrap\">${customersListContent(state.customers)}</div>\n          </div>\n          <form class=\"panel form-grid\" id=\"customerForm\">\n            <div class=\"field full\"><h2>לקוח חדש / עריכה</h2></div>\n            ${hiddenId('customerId')}\n            ${field('שם פרטי', 'customerFirstName')}\n            ${field('שם משפחה', 'customerLastName')}\n            ${field('טלפון', 'customerPhone', 'tel')}\n            ${field('כתובת', 'customerAddress')}\n            ${field('עיר', 'customerCity')}\n            ${area('הערות משלוח', 'customerDeliveryNotes')}\n            <div class=\"field full toolbar\"><button class=\"button primary\" id=\"saveCustomer\" type=\"submit\">שמירה</button><button class=\"button ghost\" id=\"clearCustomer\" type=\"button\">ניקוי</button></div>\n          </form>\n        </div>`;\n    }\n\n    function customersListContent(rows) {\n      if (customersLoadState === 'loading') return '<div class=\"empty\">טוען לקוחות מהשרת...</div>';\n      if (customersLoadState === 'error') {\n        return `<div class=\"empty\">טעינת הלקוחות נכשלה: ${escapeHtml(customersLoadError)}<br><button class=\"button ghost\" id=\"reloadCustomers\" type=\"button\">נסה שוב</button></div>`;\n      }\n      return customersTable(rows);\n    }\n\n    function customersTable(rows) {\n      if (!rows.length) return '<div class=\"empty\">אין לקוחות להצגה</div>';\n      return `<table><thead><tr><th>שם מלא</th><th>טלפון</th><th>עיר</th><th>הזמנה אחרונה</th><th>מספר הזמנות</th><th>סך רכישות</th><th>פעולות</th></tr></thead><tbody>${rows.map((item) => {\n        const metrics = customerMetrics(item.id);\n        return `\n        <tr>\n          <td><strong>${customerName(item)}</strong><br><span class=\"muted\">${item.address || '-'}</span></td>\n          <td class=\"nowrap\">${item.phone}</td>\n          <td>${item.city || '-'}</td>\n          <td>${metrics.lastOrderDate || '-'}</td>\n          <td>${metrics.orderCount}</td>\n          <td><strong>${shekel(metrics.total)}</strong></td>\n          <td><div class=\"row-actions\"><button class=\"mini\" data-open-customer=\"${item.id}\" type=\"button\">פתיחה</button><button class=\"mini\" data-edit-customer=\"${item.id}\" type=\"button\">עריכה</button><button class=\"mini\" data-order-customer=\"${item.id}\" type=\"button\">הזמנה</button><button class=\"mini danger\" data-delete-customer=\"${item.id}\" type=\"button\">מחיקה</button></div></td>\n        </tr>`;\n      }).join('')}</tbody></table>`;\n    }\n\n    function deletedCustomersView() {\n      if (deletedCustomersLoadState === 'loading') return '<div class=\"empty\">טוען לקוחות מחוקים...</div>';\n      if (deletedCustomersLoadState === 'error') {\n        return `<div class=\"empty\">טעינת הארכיון נכשלה: ${escapeHtml(deletedCustomersLoadError)}<br><button class=\"button ghost\" id=\"reloadDeletedCustomers\" type=\"button\">נסה שוב</button></div>`;\n      }\n      if (!deletedCustomers.length) return '<div class=\"empty\">אין לקוחות מחוקים בארכיון</div>';\n      return `\n        <div class=\"panel\">\n          <div class=\"panel-head\"><h2>ארכיון לקוחות מחוקים</h2><button class=\"button ghost\" id=\"reloadDeletedCustomers\" type=\"button\">רענון</button></div>\n          <div class=\"table-wrap\"><table><thead><tr><th>שם מלא</th><th>טלפון</th><th>עיר</th><th>נמחק בתאריך</th><th>פעולות</th></tr></thead><tbody>${deletedCustomers.map((item) => `\n            <tr>\n              <td><strong>${customerName(item)}</strong><br><span class=\"muted break-word\">${item.address || '-'}</span></td>\n              <td class=\"nowrap\">${item.phone}</td>\n              <td>${item.city || '-'}</td>\n              <td>${item.deletedAt ? item.deletedAt.slice(0, 10) : '-'}</td>\n              <td><button class=\"mini\" data-open-deleted-customer=\"${item.id}\" type=\"button\">פתיחה</button></td>\n            </tr>`).join('')}</tbody></table></div>\n        </div>`;\n    }\n\n    function customerProfileView() {\n      const item = customer(state.selected.customerProfileId) || deletedCustomers.find((deleted) => deleted.id === state.selected.customerProfileId);\n      if (!item) return '<div class=\"empty\">לקוח לא נמצא</div>';\n      const metrics = customerMetrics(item.id);\n      const orders = customerOrders(item.id);\n      const invoices = customerInvoices(item.id);\n      const prices = customerPrices(item.id);\n      return `\n        <div class=\"profile-grid\">\n          <div class=\"profile-stack\">\n            <div class=\"panel\">\n              <div class=\"panel-head\"><h2>פרטי לקוח</h2><div class=\"row-actions\"><button class=\"mini\" data-edit-customer=\"${item.id}\" type=\"button\">עריכה</button>${item.deletedAt ? '' : `<button class=\"mini danger\" data-delete-customer=\"${item.id}\" type=\"button\">מחיקה</button>`}</div></div>\n              <div class=\"detail-list\">\n                <div><span>שם מלא</span><strong>${customerName(item)}</strong></div>\n                <div><span>טלפון</span><strong class=\"nowrap\">${item.phone || '-'}</strong></div>\n                <div><span>עיר</span>${item.city || '-'}</div>\n                <div><span>כתובת</span>${item.address || '-'}</div>\n                <div class=\"field full\"><span>הערות משלוח</span>${item.deliveryNotes || 'אין הערות משלוח'}</div>\n              </div>\n            </div>\n            <div class=\"panel\">\n              <div class=\"panel-head\"><h2>הזמנות קשורות</h2><button class=\"button ghost\" data-order-customer=\"${item.id}\" type=\"button\">מסך הזמנה מלא</button></div>\n              ${customerOrdersSummary(orders)}\n            </div>\n            <div class=\"panel\">\n              <div class=\"panel-head\"><h2>חשבוניות</h2></div>\n              ${customerInvoicesSummary(invoices)}\n            </div>\n            <div class=\"panel\">\n              <div class=\"panel-head\"><h2>מחירים אישיים</h2><button class=\"button ghost\" data-price-customer=\"${item.id}\" type=\"button\">הוסף מחיר אישי</button></div>\n              ${customerPricesSummary(prices)}\n            </div>\n          </div>\n          <div class=\"profile-stack\">\n            <div class=\"panel\">\n              <div class=\"panel-head\"><h2>מדדי לקוח</h2></div>\n              <div class=\"grid metrics\">\n                <div class=\"metric\"><span>סך רכישות</span><strong>${shekel(metrics.total)}</strong></div>\n                <div class=\"metric\"><span>מספר הזמנות</span><strong>${metrics.orderCount}</strong></div>\n                <div class=\"metric\"><span>ממוצע להזמנה</span><strong>${shekel(metrics.averageOrder)}</strong></div>\n                <div class=\"metric\"><span>הזמנה אחרונה</span><strong>${metrics.lastOrderDate || '-'}</strong></div>\n              </div>\n            </div>\n            <div class=\"panel\">\n              <div class=\"panel-head\"><h2>פעולות</h2></div>\n              <div class=\"toolbar\">\n                <button class=\"button primary\" data-quick-order-customer=\"${item.id}\" type=\"button\">הזמנה מהירה</button>\n                <button class=\"button ghost\" data-order-customer=\"${item.id}\" type=\"button\">הזמנה מלאה</button>\n                <button class=\"button ghost\" data-price-customer=\"${item.id}\" type=\"button\">מחיר אישי</button>\n                <button class=\"button ghost\" data-reset-password=\"${item.id}\" type=\"button\">איפוס סיסמה</button>\n              </div>\n              <p class=\"muted\">איפוס סיסמה מגדיר סיסמה זמנית ומחייב החלפה בכניסה הבאה. לא נשלחת הודעה חיצונית מהמסך.</p>\n            </div>\n          </div>\n        </div>`;\n    }\n\n    function customerOrdersSummary(rows) {\n      if (!rows.length) return '<div class=\"empty\">אין הזמנות ללקוח הזה</div>';\n      return `<div class=\"table-wrap\"><table><thead><tr><th>מספר</th><th>אספקה</th><th>סה\"כ</th><th>תשלום</th></tr></thead><tbody>${rows.map((order) => `\n        <tr><td><strong>${order.id}</strong><br><span class=\"muted\">${order.createdAt}</span></td><td>${order.deliveryDate || '-'}</td><td><strong>${shekel(orderTotal(order))}</strong></td><td><span class=\"status ${statusClass(order.paymentStatus)}\">${statusLabel(order.paymentStatus)}</span></td></tr>`).join('')}</tbody></table></div>`;\n    }\n\n    function customerInvoicesSummary(rows) {\n      if (!rows.length) return '<div class=\"empty\">אין חשבוניות להצגה. מקור עתידי צפוי להיות Meshulam / Grow.</div>';\n      return `<div class=\"table-wrap\"><table><thead><tr><th>מספר</th><th>תאריך</th><th>סכום</th><th>סטטוס</th><th>קישור</th></tr></thead><tbody>${rows.map((invoice) => `\n        <tr><td>${invoice.invoiceNumber}</td><td>${invoice.date || '-'}</td><td><strong>${shekel(invoice.amount)}</strong></td><td><span class=\"status ${statusClass(invoice.paymentStatus)}\">${statusLabel(invoice.paymentStatus)}</span></td><td><a class=\"break-word\" href=\"${invoice.link}\" target=\"_blank\" rel=\"noreferrer\">פתיחה</a></td></tr>`).join('')}</tbody></table></div>`;\n    }\n\n    function customerPricesSummary(rows) {\n      if (!rows.length) return '<div class=\"empty\">אין מחירים אישיים ללקוח הזה</div>';\n      return `<div class=\"table-wrap\"><table><thead><tr><th>מוצר</th><th>מחיר אישי</th><th>הנחה</th><th>מחיר להזמנה</th></tr></thead><tbody>${rows.map((price) => `\n        <tr><td>${product(price.productId)?.name || '-'}</td><td>${Number(price.customPrice || 0) > 0 ? shekel(price.customPrice) : '-'}</td><td>${price.discountPercent || 0}%</td><td><strong>${shekel(priceFor(price.customerId, price.productId))}</strong></td></tr>`).join('')}</tbody></table></div>`;\n    }\n\n    function productsView() {\n      return `\n        <div class=\"split\">\n          <div class=\"panel\">\n            <div class=\"panel-head\"><h2>מוצרים</h2></div>\n            <div class=\"table-wrap\">${productsTable()}</div>\n          </div>\n          <form class=\"panel form-grid\" id=\"productForm\">\n            <div class=\"field full\"><h2>מוצר חדש / עריכה</h2></div>\n            ${hiddenId('productId')}\n            ${field('מותג', 'productBrand')}\n            ${field('סדרה', 'productSeries')}\n            ${field('חיה', 'productAnimal')}\n            ${field('שלב חיים', 'productStage')}\n            ${field('טעם', 'productFlavor')}\n            ${field('משקל ק\"ג', 'productWeight', 'number')}\n            ${field('שם תצוגה', 'productName')}\n            ${field('מחיר בסיס', 'productPrice', 'number')}\n            <div class=\"field\"><label>פעיל</label><select id=\"productActive\"><option value=\"true\">כן</option><option value=\"false\">לא</option></select></div>\n            <div class=\"field full toolbar\"><button class=\"button primary\" type=\"submit\">שמירה</button><button class=\"button ghost\" id=\"clearProduct\" type=\"button\">ניקוי</button></div>\n          </form>\n        </div>`;\n    }\n\n    function productsTable() {\n      return `<table><thead><tr><th>מוצר</th><th>מאפיינים</th><th>מחיר בסיס</th><th>סטטוס</th><th>פעולות</th></tr></thead><tbody>${state.products.map((item) => `\n        <tr>\n          <td><strong>${item.name}</strong><br><span class=\"muted\">${item.brand} ${item.series}</span></td>\n          <td>${item.animal} / ${item.stage}<br><span class=\"muted\">${item.flavor}, ${item.weightKg} ק\"ג</span></td>\n          <td>${shekel(item.basePrice)}</td>\n          <td><span class=\"status ${item.active ? 'ok' : 'danger'}\">${item.active ? 'פעיל' : 'לא פעיל'}</span></td>\n          <td><button class=\"mini\" data-edit-product=\"${item.id}\" type=\"button\">עריכה</button></td>\n        </tr>`).join('')}</tbody></table>`;\n    }\n\n    function pricingView() {\n      return `\n        <div class=\"split\">\n          <div class=\"panel\">\n            <div class=\"panel-head\"><h2>מחירים אישיים</h2></div>\n            <div class=\"table-wrap\"><table><thead><tr><th>לקוח</th><th>מוצר</th><th>מחיר אישי</th><th>הנחה</th><th>מחיר להזמנה</th><th>פעולות</th></tr></thead><tbody>${state.prices.map((item) => `\n              <tr>\n                <td>${customerName(customer(item.customerId))}</td>\n                <td>${product(item.productId)?.name || '-'}</td>\n                <td>${Number(item.customPrice || 0) > 0 ? shekel(item.customPrice) : '-'}</td>\n                <td>${item.discountPercent || 0}%</td>\n                <td><strong>${shekel(priceFor(item.customerId, item.productId))}</strong></td>\n                <td><button class=\"mini\" data-delete-price=\"${item.id}\" type=\"button\">מחיקה</button></td>\n              </tr>`).join('')}</tbody></table></div>\n          </div>\n          <form class=\"panel form-grid\" id=\"priceForm\">\n            <div class=\"field full\"><h2>הוספת כלל מחיר</h2></div>\n            <div class=\"field full\"><label>לקוח</label>${customerSelect('priceCustomer')}</div>\n            <div class=\"field full\"><label>מוצר</label>${productSelect('priceProduct')}</div>\n            ${field('מחיר אישי', 'customPrice', 'number')}\n            ${field('הנחה %', 'discountPercent', 'number')}\n            ${area('הערות', 'priceNotes')}\n            <div class=\"field full toolbar\"><button class=\"button primary\" type=\"submit\">שמירה</button></div>\n          </form>\n        </div>`;\n    }\n\n    function ordersView() {\n      return `\n        <div class=\"split\">\n          <div class=\"panel\">\n            <div class=\"panel-head\"><h2>הזמנות</h2></div>\n            <div class=\"filters\">\n              <select id=\"orderPaymentFilter\"><option value=\"\">כל התשלומים</option><option value=\"pending_online_payment\">ממתין לתשלום</option><option value=\"cash_on_delivery\">מזומן לשליח</option><option value=\"paid_online\">שולם אונליין</option><option value=\"paid_cash\">שולם במזומן</option></select>\n              <input id=\"orderAreaFilter\" placeholder=\"סינון עיר/אזור\">\n              <input id=\"orderDateFilter\" type=\"date\">\n              <button class=\"button ghost\" id=\"clearOrderFilters\" type=\"button\">ניקוי</button>\n            </div>\n            <div id=\"ordersTable\">${ordersTable(state.orders)}</div>\n          </div>\n          <form class=\"panel order-builder\" id=\"orderForm\">\n            <h2>הזמנה ידנית</h2>\n            <div class=\"field\"><label>לקוח</label>${customerSelect('orderCustomer')}</div>\n            <div id=\"orderItems\"></div>\n            <button class=\"button ghost\" id=\"addOrderItem\" type=\"button\">הוספת מוצר</button>\n            <div class=\"form-grid\">\n              <div class=\"field\"><label>תאריך אספקה</label><input id=\"deliveryDate\" type=\"date\" value=\"${today()}\"></div>\n              <div class=\"field\"><label>סטטוס תשלום</label><select id=\"paymentStatus\"><option value=\"pending_online_payment\">ממתין לתשלום</option><option value=\"cash_on_delivery\">מזומן לשליח</option><option value=\"paid_cash\">שולם במזומן</option><option value=\"paid_online\">שולם אונליין</option></select></div>\n            </div>\n            ${area('הערות', 'orderNotes')}\n            <div class=\"total-line\"><span>סה\"כ</span><span id=\"orderTotal\">₪0</span></div>\n            <button class=\"button primary\" type=\"submit\">יצירת הזמנה</button>\n          </form>\n        </div>`;\n    }\n\n    function ordersTable(rows) {\n      if (!rows.length) return '<div class=\"empty\">אין הזמנות להצגה</div>';\n      return `<div class=\"table-wrap\"><table><thead><tr><th>מספר</th><th>לקוח</th><th>אספקה</th><th>פריטים</th><th>סה\"כ</th><th>תשלום</th><th>פעולות</th></tr></thead><tbody>${rows.map((order) => {\n        const c = customer(order.customerId);\n        return `<tr>\n          <td><strong>${order.id}</strong><br><span class=\"muted\">${order.createdAt}</span></td>\n          <td>${customerName(c)}<br><span class=\"muted\">${c ? `${c.city || ''}` : ''}</span></td>\n          <td>${order.deliveryDate || '-'}<br><span class=\"status ${statusClass(order.status)}\">${statusLabel(order.status)}</span></td>\n          <td>${order.items.map((item) => `${product(item.productId)?.name || '-'} × ${item.quantity}`).join('<br>')}</td>\n          <td><strong>${shekel(orderTotal(order))}</strong></td>\n          <td><span class=\"status ${statusClass(order.paymentStatus)}\">${statusLabel(order.paymentStatus)}</span></td>\n          <td><div class=\"row-actions\"><button class=\"mini\" data-pay-link=\"${order.id}\" type=\"button\">קישור תשלום</button><button class=\"mini\" data-mark-paid=\"${order.id}\" type=\"button\">סמן שולם</button><button class=\"mini\" data-delivered=\"${order.id}\" type=\"button\">סופק</button></div></td>\n        </tr>`;\n      }).join('')}</tbody></table></div>`;\n    }\n\n    function deliveriesView() {\n      const rows = state.orders.slice().sort((a, b) => (a.deliveryDate || '').localeCompare(b.deliveryDate || ''));\n      return `\n        <div class=\"panel\">\n          <div class=\"panel-head\"><h2>משלוחים קרובים</h2><input id=\"deliveryFilter\" placeholder=\"סינון לפי עיר, אזור או לקוח\"></div>\n          <div class=\"list\" id=\"deliveryList\">${deliveryCards(rows)}</div>\n        </div>`;\n    }\n\n    function deliveryCards(rows) {\n      if (!rows.length) return '<div class=\"empty\">אין משלוחים להצגה</div>';\n      return rows.map((order) => {\n        const c = customer(order.customerId);\n        const cash = order.paymentStatus === 'cash_on_delivery';\n        return `<article class=\"delivery-card ${cash ? 'cash' : ''}\">\n          <strong>${order.deliveryDate || 'ללא תאריך'} | ${customerName(c)}</strong>\n          <p class=\"muted\">${c?.address || ''}, ${c?.city || ''}</p>\n          <p>${order.items.map((item) => `${product(item.productId)?.name || '-'} × ${item.quantity}`).join('<br>')}</p>\n          <p><span class=\"status ${statusClass(order.paymentStatus)}\">${statusLabel(order.paymentStatus)}</span> <strong>${shekel(orderTotal(order))}</strong></p>\n          ${order.notes ? `<p class=\"muted\">${order.notes}</p>` : ''}\n        </article>`;\n      }).join('');\n    }\n\n    function settingsView() {\n      return `\n        <div class=\"grid\">\n          <div class=\"panel\"><div class=\"panel-head\"><h2>סטטוסים חיצוניים</h2></div>\n            <div class=\"grid metrics\">\n              <div class=\"metric\"><span>Grow / משולם</span><strong>Stub</strong></div>\n              <div class=\"metric\"><span>לינק סיסמה ראשוני</span><strong>TBD</strong></div>\n              <div class=\"metric\"><span>ייבוא לקוחות</span><strong>TBD</strong></div>\n              <div class=\"metric\"><span>חשבוניות מזומן</span><strong>TBD</strong></div>\n            </div>\n          </div>\n          <div class=\"panel\"><h2>כללי אבטחה שנקבעו</h2><p class=\"muted\">לקוחות נוצרים רק על ידי בעל העסק. בפורטל הלקוח העתידי תהיה כניסה עם טלפון וסיסמה, סיסמה זמנית/לינק ראשוני, והחלפת סיסמה חובה בכניסה הראשונה.</p></div>\n        </div>`;\n    }\n\n    function field(labelText, id, type = 'text') {\n      return `<div class=\"field\"><label>${labelText}</label><input id=\"${id}\" type=\"${type}\"></div>`;\n    }\n\n    function area(labelText, id) {\n      return `<div class=\"field full\"><label>${labelText}</label><textarea id=\"${id}\"></textarea></div>`;\n    }\n\n    function escapeHtml(value) {\n      return String(value ?? '').replace(/[&<>\"']/g, (char) => ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;'\n      })[char]);\n    }\n\n    function hiddenId(id) {\n      return `<input id=\"${id}\" type=\"hidden\">`;\n    }\n\n    function customerSelect(id) {\n      return `<select id=\"${id}\">${state.customers.filter((item) => item.active !== false && !item.deletedAt).map((item) => `<option value=\"${item.id}\">${customerName(item)} | ${item.phone}</option>`).join('')}</select>`;\n    }\n\n    function productSelect(id) {\n      return `<select id=\"${id}\">${state.products.filter((item) => item.active).map((item) => `<option value=\"${item.id}\">${item.name} | ${shekel(item.basePrice)}</option>`).join('')}</select>`;\n    }\n\n    function bindView() {\n      document.querySelectorAll('[data-goto]').forEach((button) => button.addEventListener('click', () => { currentTab = button.dataset.goto; render(); }));\n      document.querySelectorAll('[data-open-customer]').forEach((button) => button.addEventListener('click', () => openCustomerProfile(button.dataset.openCustomer)));\n      document.querySelectorAll('[data-open-deleted-customer]').forEach((button) => button.addEventListener('click', () => openCustomerProfile(button.dataset.openDeletedCustomer)));\n      document.querySelectorAll('[data-edit-customer]').forEach((button) => button.addEventListener('click', () => editCustomer(button.dataset.editCustomer)));\n      document.querySelectorAll('[data-delete-customer]').forEach((button) => button.addEventListener('click', () => deleteCustomer(button.dataset.deleteCustomer)));\n      document.querySelectorAll('[data-order-customer]').forEach((button) => button.addEventListener('click', () => openOrdersForCustomer(button.dataset.orderCustomer)));\n      document.querySelectorAll('[data-price-customer]').forEach((button) => button.addEventListener('click', () => openPricingForCustomer(button.dataset.priceCustomer)));\n      document.querySelectorAll('[data-quick-order-customer]').forEach((button) => button.addEventListener('click', () => openQuickOrderModal(button.dataset.quickOrderCustomer)));\n      document.querySelectorAll('[data-reset-password]').forEach((button) => button.addEventListener('click', () => resetCustomerPassword(button.dataset.resetPassword)));\n      document.getElementById('reloadDeletedCustomers')?.addEventListener('click', loadDeletedCustomersFromServer);\n      bindCustomers();\n      bindProducts();\n      bindPricing();\n      bindOrders();\n      bindDeliveries();\n    }\n\n    function bindCustomers() {\n      const form = document.getElementById('customerForm');\n      if (!form) return;\n      document.getElementById('reloadCustomers')?.addEventListener('click', loadCustomersFromServer);\n      document.getElementById('customerSearch').addEventListener('input', (event) => {\n        const q = event.target.value.trim().toLowerCase();\n        const rows = state.customers.filter((item) => [customerName(item), item.address, item.phone, item.city].join(' ').toLowerCase().includes(q));\n        document.querySelector('.table-wrap').innerHTML = customersListContent(rows);\n        bindCustomerRows();\n      });\n      document.getElementById('clearCustomer').addEventListener('click', () => {\n        form.reset();\n        setValue('customerId', '');\n      });\n      form.addEventListener('submit', async (event) => {\n        event.preventDefault();\n        const id = document.getElementById('customerId').value;\n        const item = {\n          firstName: value('customerFirstName'),\n          lastName: value('customerLastName'),\n          phone: value('customerPhone'),\n          address: value('customerAddress'),\n          city: value('customerCity'),\n          deliveryNotes: value('customerDeliveryNotes')\n        };\n        if (!item.firstName || !item.lastName || !item.phone) return toast('צריך שם פרטי, שם משפחה וטלפון');\n        const saveButton = document.getElementById('saveCustomer');\n        customersSaving = true;\n        saveButton.disabled = true;\n        saveButton.textContent = 'שומר...';\n        try {\n          const data = await customerApi(id ? `/api/customers/${encodeURIComponent(id)}` : '/api/customers', {\n            method: id ? 'PATCH' : 'POST',\n            body: JSON.stringify(item)\n          });\n          const savedCustomer = normalizeCustomer(data.customer);\n          upsert(state.customers, savedCustomer);\n          localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n          form.reset();\n          setValue('customerId', '');\n          toast('לקוח נשמר');\n          render();\n        } catch (error) {\n          toast(error.message || 'שמירת הלקוח נכשלה');\n        } finally {\n          customersSaving = false;\n          if (document.body.contains(saveButton)) {\n            saveButton.disabled = false;\n            saveButton.textContent = 'שמירה';\n          }\n        }\n      });\n    }\n\n    function bindCustomerRows() {\n      document.querySelectorAll('[data-open-customer]').forEach((button) => button.addEventListener('click', () => openCustomerProfile(button.dataset.openCustomer)));\n      document.querySelectorAll('[data-edit-customer]').forEach((button) => button.addEventListener('click', () => editCustomer(button.dataset.editCustomer)));\n      document.querySelectorAll('[data-order-customer]').forEach((button) => button.addEventListener('click', () => openOrdersForCustomer(button.dataset.orderCustomer)));\n      document.querySelectorAll('[data-delete-customer]').forEach((button) => button.addEventListener('click', () => deleteCustomer(button.dataset.deleteCustomer)));\n    }\n\n    function editCustomer(id) {\n      currentTab = 'customers';\n      render();\n      fillCustomer(id);\n    }\n\n    function fillCustomer(id) {\n      const item = customer(id);\n      if (!item) return;\n      setValue('customerId', item.id);\n      setValue('customerFirstName', item.firstName);\n      setValue('customerLastName', item.lastName);\n      setValue('customerPhone', item.phone);\n      setValue('customerAddress', item.address);\n      setValue('customerCity', item.city);\n      setValue('customerDeliveryNotes', item.deliveryNotes);\n    }\n\n    async function deleteCustomer(id) {\n      const item = customer(id);\n      if (!item) return;\n      if (!confirm(`למחוק את ${customerName(item)} ולהעביר לארכיון לקוחות מחוקים?`)) return;\n      try {\n        await customerApi(`/api/customers/${encodeURIComponent(id)}`, { method: 'DELETE' });\n        state.customers = state.customers.filter((customerItem) => customerItem.id !== id);\n        state.prices = state.prices.filter((price) => price.customerId !== id);\n        if (state.selected.customerId === id) state.selected.customerId = state.customers[0]?.id || '';\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n        toast('הלקוח הועבר לארכיון');\n        render();\n      } catch (error) {\n        toast(error.message || 'מחיקת הלקוח נכשלה');\n      }\n    }\n\n    function openCustomerProfile(id) {\n      state.selected.customerProfileId = id;\n      currentTab = 'customerProfile';\n      render();\n    }\n\n    function openOrdersForCustomer(id) {\n      state.selected.customerId = id;\n      currentTab = 'orders';\n      render();\n    }\n\n    function openPricingForCustomer(id) {\n      state.selected.customerId = id;\n      currentTab = 'pricing';\n      render();\n    }\n\n    async function resetCustomerPassword(id) {\n      const item = customer(id);\n      if (!item) return;\n      if (!confirm(`לאפס סיסמה ל-${customerName(item)}?`)) return;\n      try {\n        const data = await customerApi(`/api/customers/${encodeURIComponent(id)}/reset-password`, { method: 'POST' });\n        upsert(state.customers, normalizeCustomer(data.customer));\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n        toast('הסיסמה אופסה. הלקוח יחויב להחליף סיסמה בכניסה הבאה');\n        render();\n      } catch (error) {\n        toast(error.message || 'איפוס הסיסמה נכשל');\n      }\n    }\n\n    function openQuickOrderModal(customerId) {\n      const item = customer(customerId);\n      if (!item) return toast('לקוח לא נמצא');\n      const root = document.getElementById('modalRoot');\n      root.innerHTML = `\n        <div class=\"modal\">\n          <div class=\"panel-head\"><h2>הזמנה מהירה | ${customerName(item)}</h2><button class=\"mini\" id=\"closeModal\" type=\"button\">סגירה</button></div>\n          <form class=\"order-builder\" id=\"quickOrderForm\">\n            <div class=\"field\"><label>מוצר</label>${productSelect('quickOrderProduct')}</div>\n            <div class=\"field\"><label>כמות</label><input id=\"quickOrderQty\" type=\"number\" min=\"1\" value=\"1\"></div>\n            <div class=\"field\"><label>תאריך אספקה</label><input id=\"quickDeliveryDate\" type=\"date\" value=\"${today()}\"></div>\n            <div class=\"field\"><label>סטטוס תשלום</label><select id=\"quickPaymentStatus\"><option value=\"pending_online_payment\">ממתין לתשלום</option><option value=\"cash_on_delivery\">מזומן לשליח</option><option value=\"paid_cash\">שולם במזומן</option><option value=\"paid_online\">שולם אונליין</option></select></div>\n            ${area('הערות להזמנה', 'quickOrderNotes')}\n            <div class=\"total-line\"><span>סה\"כ</span><span id=\"quickOrderTotal\">₪0</span></div>\n            <button class=\"button primary\" type=\"submit\">יצירת הזמנה</button>\n          </form>\n        </div>`;\n      root.classList.remove('hidden');\n      document.getElementById('closeModal').addEventListener('click', closeModal);\n      document.getElementById('quickOrderProduct').value = state.selected.productId || state.products[0]?.id || '';\n      ['quickOrderProduct', 'quickOrderQty'].forEach((id) => document.getElementById(id).addEventListener('input', () => recalcQuickOrder(customerId)));\n      document.getElementById('quickOrderForm').addEventListener('submit', (event) => {\n        event.preventDefault();\n        const productId = value('quickOrderProduct');\n        const quantity = Number(value('quickOrderQty') || 0);\n        if (!productId || quantity <= 0) return toast('צריך לבחור מוצר וכמות');\n        const id = nextId('o', state.orders);\n        const paymentStatus = value('quickPaymentStatus');\n        state.orders.push({\n          id,\n          customerId,\n          createdAt: today(),\n          deliveryDate: value('quickDeliveryDate'),\n          status: paymentStatus === 'paid_online' || paymentStatus === 'paid_cash' ? 'confirmed' : 'new',\n          paymentStatus,\n          source: 'manual',\n          paymentUrl: paymentStatus === 'pending_online_payment' ? `https://pay.example.test/orders/${id}` : '',\n          notes: value('quickOrderNotes'),\n          items: [{ productId, quantity, unitPrice: priceFor(customerId, productId) }]\n        });\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n        closeModal();\n        toast('הזמנה מהירה נוצרה');\n        render();\n      });\n      recalcQuickOrder(customerId);\n    }\n\n    function recalcQuickOrder(customerId) {\n      const productId = value('quickOrderProduct');\n      const quantity = Number(value('quickOrderQty') || 0);\n      document.getElementById('quickOrderTotal').textContent = shekel(priceFor(customerId, productId) * quantity);\n    }\n\n    function closeModal() {\n      const root = document.getElementById('modalRoot');\n      root.classList.add('hidden');\n      root.innerHTML = '';\n    }\n\n    function bindProducts() {\n      const form = document.getElementById('productForm');\n      if (!form) return;\n      document.querySelectorAll('[data-edit-product]').forEach((button) => button.addEventListener('click', () => fillProduct(button.dataset.editProduct)));\n      document.getElementById('clearProduct').addEventListener('click', () => form.reset());\n      form.addEventListener('submit', (event) => {\n        event.preventDefault();\n        const id = value('productId') || nextId('p', state.products);\n        const item = {\n          id,\n          brand: value('productBrand'),\n          series: value('productSeries'),\n          animal: value('productAnimal'),\n          stage: value('productStage'),\n          flavor: value('productFlavor'),\n          weightKg: Number(value('productWeight') || 0),\n          name: value('productName'),\n          basePrice: Number(value('productPrice') || 0),\n          active: value('productActive') === 'true'\n        };\n        if (!item.name || !item.basePrice) return toast('צריך שם מוצר ומחיר בסיס');\n        upsert(state.products, item);\n        saveState('מוצר נשמר');\n      });\n    }\n\n    function fillProduct(id) {\n      const item = product(id);\n      if (!item) return;\n      setValue('productId', item.id);\n      setValue('productBrand', item.brand);\n      setValue('productSeries', item.series);\n      setValue('productAnimal', item.animal);\n      setValue('productStage', item.stage);\n      setValue('productFlavor', item.flavor);\n      setValue('productWeight', item.weightKg);\n      setValue('productName', item.name);\n      setValue('productPrice', item.basePrice);\n      setValue('productActive', String(item.active));\n    }\n\n    function bindPricing() {\n      const form = document.getElementById('priceForm');\n      if (!form) return;\n      const priceCustomerNode = document.getElementById('priceCustomer');\n      if (state.selected.customerId) priceCustomerNode.value = state.selected.customerId;\n      document.querySelectorAll('[data-delete-price]').forEach((button) => button.addEventListener('click', () => {\n        state.prices = state.prices.filter((item) => item.id !== button.dataset.deletePrice);\n        saveState('כלל מחיר נמחק');\n      }));\n      form.addEventListener('submit', (event) => {\n        event.preventDefault();\n        const item = {\n          id: nextId('cp', state.prices),\n          customerId: value('priceCustomer'),\n          productId: value('priceProduct'),\n          customPrice: Number(value('customPrice') || 0),\n          discountPercent: Number(value('discountPercent') || 0),\n          notes: value('priceNotes')\n        };\n        state.prices = state.prices.filter((price) => !(price.customerId === item.customerId && price.productId === item.productId));\n        state.prices.push(item);\n        saveState('מחיר אישי נשמר');\n      });\n    }\n\n    function bindOrders() {\n      const form = document.getElementById('orderForm');\n      if (!form) return;\n      const customerSelectNode = document.getElementById('orderCustomer');\n      if (state.selected.customerId) customerSelectNode.value = state.selected.customerId;\n      renderOrderItems([{ productId: state.selected.productId || state.products[0]?.id, quantity: 1 }]);\n      customerSelectNode.addEventListener('change', recalcOrder);\n      document.getElementById('addOrderItem').addEventListener('click', () => {\n        const items = readOrderItems();\n        items.push({ productId: state.products[0]?.id, quantity: 1 });\n        renderOrderItems(items);\n      });\n      document.getElementById('clearOrderFilters').addEventListener('click', () => {\n        setValue('orderPaymentFilter', '');\n        setValue('orderAreaFilter', '');\n        setValue('orderDateFilter', '');\n        filterOrders();\n      });\n      ['orderPaymentFilter', 'orderAreaFilter', 'orderDateFilter'].forEach((id) => document.getElementById(id).addEventListener('input', filterOrders));\n      bindOrderActionButtons();\n      form.addEventListener('submit', (event) => {\n        event.preventDefault();\n        const customerId = value('orderCustomer');\n        const items = readOrderItems().map((item) => ({ ...item, unitPrice: priceFor(customerId, item.productId) })).filter((item) => item.productId && item.quantity > 0);\n        if (!items.length) return toast('צריך לפחות פריט אחד');\n        const id = nextId('o', state.orders);\n        const paymentStatus = value('paymentStatus');\n        state.orders.push({\n          id,\n          customerId,\n          createdAt: today(),\n          deliveryDate: value('deliveryDate'),\n          status: paymentStatus === 'paid_online' || paymentStatus === 'paid_cash' ? 'confirmed' : 'new',\n          paymentStatus,\n          source: 'manual',\n          paymentUrl: paymentStatus === 'pending_online_payment' ? `https://pay.example.test/orders/${id}` : '',\n          notes: value('orderNotes'),\n          items\n        });\n        saveState('הזמנה נוצרה');\n      });\n    }\n\n    function renderOrderItems(items) {\n      document.getElementById('orderItems').innerHTML = items.map((item, index) => `\n        <div class=\"item-row\" data-order-row>\n          <div class=\"field\"><label>מוצר</label>${productSelect(`orderProduct${index}`)}</div>\n          <div class=\"field\"><label>כמות</label><input id=\"orderQty${index}\" type=\"number\" min=\"1\" value=\"${item.quantity || 1}\"></div>\n          <button class=\"mini\" data-remove-order-item=\"${index}\" type=\"button\">×</button>\n        </div>`).join('');\n      items.forEach((item, index) => {\n        setValue(`orderProduct${index}`, item.productId);\n        document.getElementById(`orderProduct${index}`).addEventListener('change', recalcOrder);\n        document.getElementById(`orderQty${index}`).addEventListener('input', recalcOrder);\n      });\n      document.querySelectorAll('[data-remove-order-item]').forEach((button) => button.addEventListener('click', () => {\n        const next = readOrderItems().filter((_, index) => index !== Number(button.dataset.removeOrderItem));\n        renderOrderItems(next.length ? next : [{ productId: state.products[0]?.id, quantity: 1 }]);\n      }));\n      recalcOrder();\n    }\n\n    function readOrderItems() {\n      return Array.from(document.querySelectorAll('[data-order-row]')).map((_, index) => ({\n        productId: value(`orderProduct${index}`),\n        quantity: Number(value(`orderQty${index}`) || 0)\n      }));\n    }\n\n    function recalcOrder() {\n      const customerId = value('orderCustomer');\n      const total = readOrderItems().reduce((sum, item) => sum + priceFor(customerId, item.productId) * item.quantity, 0);\n      document.getElementById('orderTotal').textContent = shekel(total);\n    }\n\n    function filterOrders() {\n      const payment = value('orderPaymentFilter');\n      const area = value('orderAreaFilter').toLowerCase();\n      const date = value('orderDateFilter');\n      const rows = state.orders.filter((order) => {\n        const c = customer(order.customerId);\n        const areaText = [c?.city, customerName(c), c?.address].join(' ').toLowerCase();\n        return (!payment || order.paymentStatus === payment) && (!area || areaText.includes(area)) && (!date || order.deliveryDate === date);\n      });\n      document.getElementById('ordersTable').innerHTML = ordersTable(rows);\n      bindOrderActionButtons();\n    }\n\n    function bindOrderActionButtons() {\n      document.querySelectorAll('[data-pay-link]').forEach((button) => button.addEventListener('click', () => {\n        const order = state.orders.find((item) => item.id === button.dataset.payLink);\n        if (!order.paymentUrl) order.paymentUrl = `https://pay.example.test/orders/${order.id}`;\n        navigator.clipboard?.writeText(order.paymentUrl);\n        saveState('קישור תשלום דמו נוצר והועתק אם הדפדפן מאפשר');\n      }));\n      document.querySelectorAll('[data-mark-paid]').forEach((button) => button.addEventListener('click', () => {\n        const order = state.orders.find((item) => item.id === button.dataset.markPaid);\n        order.paymentStatus = 'paid_online';\n        order.status = 'confirmed';\n        saveState('הזמנה סומנה כשולמה');\n      }));\n      document.querySelectorAll('[data-delivered]').forEach((button) => button.addEventListener('click', () => {\n        const order = state.orders.find((item) => item.id === button.dataset.delivered);\n        order.status = 'delivered';\n        saveState('הזמנה סומנה כסופקה');\n      }));\n    }\n\n    function bindDeliveries() {\n      const filter = document.getElementById('deliveryFilter');\n      if (!filter) return;\n      filter.addEventListener('input', () => {\n        const q = filter.value.trim().toLowerCase();\n        const rows = state.orders.filter((order) => {\n          const c = customer(order.customerId);\n          return [customerName(c), c?.city, c?.address].join(' ').toLowerCase().includes(q);\n        });\n        document.getElementById('deliveryList').innerHTML = deliveryCards(rows);\n      });\n    }\n\n    function value(id) {\n      return document.getElementById(id)?.value?.trim() || '';\n    }\n\n    function setValue(id, val) {\n      const node = document.getElementById(id);\n      if (node) node.value = val ?? '';\n    }\n\n    function upsert(list, item) {\n      const index = list.findIndex((existing) => existing.id === item.id);\n      if (index >= 0) list[index] = item;\n      else list.push(item);\n    }\n\n    bindShell();\n    render();\n    loadCustomersFromServer();\n  </script>\n</body>\n</html>\n";
const customerScreenChecklistHtml = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Drive Dog | צ'קליסט מסך לקוחות</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --bg: #f7f5ef;\n      --surface: #ffffff;\n      --ink: #202124;\n      --muted: #62656a;\n      --line: #dad7ce;\n      --accent: #1f7a5c;\n      --accent-soft: #e5f3ee;\n      --warn: #9b5c00;\n      --warn-soft: #fff2d7;\n      --shadow: 0 16px 42px rgba(32, 33, 36, 0.08);\n      font-family: \"Inter\", \"Noto Sans Hebrew\", system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    body {\n      margin: 0;\n      background: var(--bg);\n      color: var(--ink);\n      line-height: 1.55;\n    }\n\n    header {\n      background: #173d33;\n      color: #fff;\n      padding: 28px 20px;\n    }\n\n    .wrap {\n      width: min(1120px, calc(100% - 32px));\n      margin: 0 auto;\n    }\n\n    .topline {\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 14px;\n    }\n\n    h1 {\n      margin: 0;\n      font-size: clamp(28px, 4vw, 44px);\n      letter-spacing: 0;\n    }\n\n    .subtitle {\n      margin: 10px 0 0;\n      max-width: 780px;\n      color: rgba(255, 255, 255, 0.82);\n      font-size: 17px;\n    }\n\n    .badge {\n      display: inline-flex;\n      align-items: center;\n      min-height: 34px;\n      border: 1px solid rgba(255, 255, 255, 0.32);\n      border-radius: 8px;\n      padding: 6px 10px;\n      color: rgba(255, 255, 255, 0.9);\n      font-size: 14px;\n      white-space: nowrap;\n    }\n\n    main {\n      padding: 22px 0 42px;\n    }\n\n    .summary {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 12px;\n      margin-bottom: 18px;\n    }\n\n    .metric {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 14px;\n      box-shadow: var(--shadow);\n    }\n\n    .metric span {\n      display: block;\n      color: var(--muted);\n      font-size: 13px;\n    }\n\n    .metric strong {\n      display: block;\n      margin-top: 4px;\n      font-size: 24px;\n    }\n\n    .decisions {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 18px;\n      margin-bottom: 18px;\n      box-shadow: var(--shadow);\n    }\n\n    h2 {\n      margin: 0 0 12px;\n      font-size: 22px;\n      letter-spacing: 0;\n    }\n\n    .decision-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 8px 18px;\n      padding: 0;\n      margin: 0;\n      list-style: none;\n    }\n\n    .decision-grid li {\n      color: var(--muted);\n      border-bottom: 1px solid #eeeae2;\n      padding: 7px 0;\n    }\n\n    .decision-grid strong {\n      color: var(--ink);\n    }\n\n    .section {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      margin: 12px 0;\n      overflow: hidden;\n      box-shadow: var(--shadow);\n    }\n\n    .section-head {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      padding: 15px 16px;\n      border-bottom: 1px solid var(--line);\n      background: #fbfaf7;\n    }\n\n    .section-title {\n      min-width: 0;\n    }\n\n    .section-title h3 {\n      margin: 0;\n      font-size: 19px;\n      letter-spacing: 0;\n    }\n\n    .branch {\n      display: inline-block;\n      margin-top: 5px;\n      color: var(--muted);\n      font-size: 13px;\n      direction: ltr;\n      unicode-bidi: plaintext;\n    }\n\n    .status {\n      border: 1px solid #d6bb78;\n      background: var(--warn-soft);\n      color: var(--warn);\n      border-radius: 8px;\n      padding: 5px 9px;\n      font-size: 13px;\n      white-space: nowrap;\n    }\n\n    .status.done {\n      border-color: #9fd0bf;\n      background: var(--accent-soft);\n      color: var(--accent);\n    }\n\n    .body {\n      padding: 14px 16px 16px;\n    }\n\n    .acceptance {\n      display: grid;\n      gap: 9px;\n      margin: 0;\n      padding: 0;\n      list-style: none;\n    }\n\n    .acceptance li {\n      display: grid;\n      grid-template-columns: 22px 1fr;\n      gap: 9px;\n      align-items: start;\n      color: #34363a;\n    }\n\n    .prompt-block {\n      margin-top: 16px;\n      border: 1px solid #d8e3df;\n      border-radius: 8px;\n      background: #f7fbf9;\n      overflow: hidden;\n    }\n\n    .prompt-title {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n      padding: 10px 12px;\n      border-bottom: 1px solid #d8e3df;\n      color: #173d33;\n      font-weight: 700;\n      font-size: 14px;\n    }\n\n    .prompt-copy {\n      margin: 0;\n      padding: 12px;\n      white-space: pre-wrap;\n      direction: rtl;\n      unicode-bidi: plaintext;\n      color: #28332f;\n      font-family: \"Noto Sans Hebrew\", \"Inter\", system-ui, sans-serif;\n      font-size: 14px;\n      line-height: 1.65;\n    }\n\n    .box {\n      width: 18px;\n      height: 18px;\n      margin-top: 3px;\n      border: 2px solid var(--accent);\n      border-radius: 4px;\n      background: var(--accent-soft);\n    }\n\n    footer {\n      color: var(--muted);\n      font-size: 13px;\n      padding: 4px 0 30px;\n    }\n\n    @media (max-width: 760px) {\n      .summary,\n      .decision-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .topline,\n      .section-head {\n        align-items: flex-start;\n        flex-direction: column;\n      }\n\n      .status {\n        white-space: normal;\n      }\n    }\n  </style>\n</head>\n<body>\n  <header>\n    <div class=\"wrap\">\n      <div class=\"topline\">\n        <div>\n          <h1>צ'קליסט מסך לקוחות</h1>\n          <p class=\"subtitle\">Drive Dog — גרסת מעקב זמנית לשלב האיפיון לפני מימוש.</p>\n        </div>\n        <span class=\"badge\">עודכן: 24.07.2026</span>\n      </div>\n    </div>\n  </header>\n\n  <main class=\"wrap\">\n    <section class=\"summary\" aria-label=\"סיכום\">\n      <div class=\"metric\"><span>יחידות עבודה</span><strong>11</strong></div>\n      <div class=\"metric\"><span>סטטוס</span><strong>3/11 בוצע</strong></div>\n      <div class=\"metric\"><span>מקור אמת</span><strong>DB</strong></div>\n      <div class=\"metric\"><span>מובייל</span><strong>חובה</strong></div>\n    </section>\n\n    <section class=\"decisions\">\n      <h2>החלטות סגורות</h2>\n      <ul class=\"decision-grid\">\n        <li><strong>משתמשים:</strong> בעל העסק והעובדים</li>\n        <li><strong>לקוח נוצר:</strong> ברגע שבעל העסק יוצר אותו</li>\n        <li><strong>טלפון:</strong> מזהה ייחודי</li>\n        <li><strong>שדות חובה:</strong> שם, שם משפחה, טלפון, כתובת, עיר, הערות משלוח</li>\n        <li><strong>מחיקה:</strong> מותרת, נשמרת בדף לקוחות מחוקים</li>\n        <li><strong>איפוס סיסמה:</strong> 123456 וחובה שינוי בכניסה הבאה</li>\n        <li><strong>חשבוניות:</strong> קישור, מספר, תאריך, סכום, סטטוס תשלום</li>\n        <li><strong>מדדים:</strong> סך רכישות, מספר הזמנות, ממוצע, הזמנה אחרונה</li>\n        <li><strong>הזמנה מתוך לקוח:</strong> מסך מלא וגם modal מהיר</li>\n        <li><strong>ייבוא:</strong> אין Excel/CSV בשלב הזה, יהיו לקוחות דמה לבדיקות</li>\n        <li><strong>הערות משלוח:</strong> לא עוברות אוטומטית להזמנה</li>\n        <li><strong>הרשאות:</strong> כל עובד יכול לערוך, למחוק ולאפס סיסמה</li>\n      </ul>\n    </section>\n\n    <div id=\"checklist\"></div>\n  </main>\n\n  <footer class=\"wrap\">\n    מקור: docs/agent-harness/CUSTOMER_SCREEN_IMPLEMENTATION_CHECKLIST.md\n  </footer>\n\n  <script>\n    const tasks = [\n      {\n        title: \"מיפוי המסך הקיים\",\n        branch: \"docs/customer-screen-audit\",\n        status: \"בוצע\",\n        items: [\n          \"ההתנהגות הנוכחית של מסך הלקוחות הסטטי מתועדת.\",\n          \"עמודות הרשימה, שדות הטופס והפעולות הקיימות מתועדים.\",\n          \"השימוש ב-localStorage כדמו בלבד מתועד.\",\n          \"הפערים למימוש אמיתי מול backend / DB רשומים.\",\n          \"אין שינוי בהתנהגות המוצר.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלתעד את ההתנהגות הקיימת של מסך הלקוחות לפני מימוש אמיתי.\n\nהקשר עסקי:\nDrive Dog הוא CRM סגור. בעל העסק והעובדים מנהלים לקוחות שנוצרו על ידי העסק. אין הרשמה פתוחה ואין checkout אנונימי.\n\nדרישות:\n- קרא את PRD.md, SPEC.md, FIRST_IMPLEMENTATION_SLICE.md, CUSTOMER_SCREEN_WORKPLAN.md ואת admin.html.\n- תעד את עמודות הרשימה, שדות הטופס והפעולות הקיימות.\n- סמן במפורש ש-localStorage הוא דמו בלבד.\n- רשום gaps למימוש backend / DB אמיתי.\n- אל תשנה קוד מוצר.\n\nAcceptance criteria:\n- יש מסמך audit קצר.\n- localStorage מסומן כדמו בלבד.\n- אין שינוי בהתנהגות האפליקציה.`\n      },\n      {\n        title: \"מודל נתוני לקוח\",\n        branch: \"feat/customer-screen-data-model\",\n        status: \"בוצע\",\n        items: [\n          \"רשומות לקוח נשמרות ב-backend / DB.\",\n          \"רענון מלא של הדף לא מאבד שינויים בלקוח.\",\n          \"קיימים שדות לפרטי לקוח, הגדרת סיסמה, חובת שינוי סיסמה וזמן מחיקה.\",\n          \"ייחודיות טלפון נאכפת.\",\n          \"לקוחות מחוקים נשמרים לדף/ארכיון לקוחות מחוקים.\",\n          \"קיימות רשומות לקוח דמה לבדיקות.\",\n          \"לא ממומש ייבוא Excel/CSV בשלב הזה.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלממש מודל נתוני לקוח מתמיד בשרת / DB.\n\nהקשר עסקי:\nלקוח נחשב לקוח ברגע שבעל העסק יוצר אותו. טלפון הוא מזהה ייחודי. אין משמעות עסקית ל-active/inactive כרגע. לקוחות מחוקים נשמרים בדף נפרד.\n\nדרישות:\n- אל תשתמש ב-localStorage כמקור אמת עסקי.\n- תמוך בשדות: שם, שם משפחה, טלפון, כתובת, עיר והערות משלוח.\n- אכוף טלפון ייחודי.\n- תמוך באיפוס סיסמה דרך hash/setup state ו-must_change_password.\n- שמור deleted_at או מנגנון שקול ללקוחות מחוקים.\n- צור לקוחות דמה לבדיקות.\n- אל תממש ייבוא Excel/CSV.\n\nAcceptance criteria:\n- יצירה ועריכה נשמרות אחרי hard refresh.\n- כפילות טלפון נחסמת עם שגיאה ברורה.\n- מחיקה מעבירה לארכיון ולא מעלימה נתונים עסקיים.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"רשימת לקוחות\",\n        branch: \"feat/customer-screen-list\",\n        status: \"בוצע\",\n        items: [\n          \"הרשימה נטענת מה-backend / DB.\",\n          \"עמודות הטבלה כוללות שם מלא, טלפון, עיר, הזמנה אחרונה, מספר הזמנות, סך רכישות ופעולות.\",\n          \"החיפוש עובד לפי שם מלא, כתובת, טלפון ועיר.\",\n          \"פעולות שורה כוללות פתיחה/צפייה, עריכה ומחיקה.\",\n          \"לקוחות מחוקים לא מופיעים ברשימה הראשית.\",\n          \"קיימים מצבי ריק, טעינה ושגיאה.\",\n          \"הטבלה/רשימה שמישה במובייל בלי גלילה אופקית בעייתית.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלבנות רשימת לקוחות מתמידה, מהירה ונוחה לסריקה.\n\nדרישות:\n- טען לקוחות מהשרת / DB.\n- הצג עמודות: שם מלא, טלפון, עיר, הזמנה אחרונה, מספר הזמנות, סך רכישות ופעולות.\n- חיפוש לפי שם מלא, כתובת, טלפון ועיר.\n- פעולות שורה: פתיחה/צפייה, עריכה ומחיקה.\n- אל תציג לקוחות מחוקים ברשימה הראשית.\n- הצג loading, empty ו-error states.\n- ודא מובייל בלי overflow.\n\nAcceptance criteria:\n- החיפוש עובד בכל השדות שאושרו.\n- לקוחות מחוקים מוסתרים מהרשימה הראשית.\n- פעולות השורה זמינות.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"יצירה, עריכה ומחיקת לקוח\",\n        branch: \"feat/customer-screen-edit-delete\",\n        items: [\n          \"בעל העסק/עובד יכול ליצור לקוח.\",\n          \"בעל העסק/עובד יכול לערוך שם, שם משפחה, טלפון, כתובת, עיר והערות משלוח.\",\n          \"קיימת ולידציה לשם, שם משפחה וטלפון.\",\n          \"שגיאת טלפון כפול ברורה למשתמש.\",\n          \"כשל שמירה לא מציג הצלחה ולא משנה מצב בצורה שגויה.\",\n          \"מחיקה דורשת אישור.\",\n          \"מחיקה מעבירה את הלקוח לדף/ארכיון לקוחות מחוקים.\",\n          \"שינוי כתובת מעדכן את הזמנות הלקוח בהתאם.\",\n          \"הערות משלוח לא מועתקות אוטומטית להזמנות חדשות.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלבנות flow אמין ליצירה, עריכה ומחיקה של לקוח.\n\nדרישות:\n- כל עובד יכול ליצור, לערוך ולמחוק לקוח.\n- ולידציה לשם, שם משפחה וטלפון.\n- טלפון חייב להיות ייחודי.\n- שמור שם, שם משפחה, טלפון, כתובת, עיר והערות משלוח.\n- שינוי כתובת מעדכן את הזמנות הלקוח בהתאם.\n- הערות משלוח לא עוברות אוטומטית להזמנה חדשה.\n- מחיקה דורשת אישור ומעבירה לדף לקוחות מחוקים.\n- כשל שמירה/מחיקה לא מציג הצלחה מזויפת.\n\nAcceptance criteria:\n- create/edit/delete עובדים מול מקור אמת.\n- כשל API משאיר מצב קודם ומציג שגיאה.\n- לקוח מחוק מופיע בארכיון.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"דף לקוחות מחוקים\",\n        branch: \"feat/customer-screen-deleted-customers\",\n        items: [\n          \"דף/תצוגה נפרדים מציגים לקוחות מחוקים.\",\n          \"לקוח מחוק מציג שם מלא, טלפון, עיר, תאריך מחיקה אם קיים ופעולת פתיחה/צפייה.\",\n          \"לקוחות מחוקים לא מופיעים כברירת מחדל בבחירת לקוח להזמנה.\",\n          \"שחזור לקוח לא נדרש אלא אם יתווסף במפורש בהמשך.\",\n          \"התצוגה שמישה במובייל.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלהציג לקוחות שנמחקו בדף/ארכיון נפרד.\n\nדרישות:\n- לקוח שנמחק לא נמחק פיזית ממקור האמת.\n- הצג דף/תצוגה נפרדים ללקוחות מחוקים.\n- הצג שם מלא, טלפון, עיר, תאריך מחיקה אם קיים ופתיחה/צפייה.\n- אל תציג לקוחות מחוקים ברשימה הראשית או בבחירת לקוח להזמנה.\n- אל תממש restore אלא אם קיימת כבר תבנית מקומית ברורה.\n- ודא מובייל.\n\nAcceptance criteria:\n- מחיקה מעבירה את הלקוח לדף לקוחות מחוקים.\n- הרשימה הראשית נקייה מלקוחות מחוקים.\n- דף הארכיון שמיש במובייל.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"פרופיל לקוח\",\n        branch: \"feat/customer-screen-detail\",\n        items: [\n          \"אזורי/טאבי הפרופיל: פרטים, הזמנות, חשבוניות, מדדים ואיפוס סיסמה.\",\n          \"הפרטים מציגים שם מלא, טלפון, כתובת, עיר והערות משלוח.\",\n          \"סיכום הזמנות מופיע בפרופיל.\",\n          \"רשימת חשבוניות מופיעה בפרופיל.\",\n          \"מדדי לקוח מופיעים בפרופיל.\",\n          \"פעולת איפוס סיסמה מופיעה בפרופיל.\",\n          \"פעולת יצירת הזמנה מלאה פותחת מסך הזמנה עם הלקוח כבר מסומן.\",\n          \"modal הזמנה מהיר נפתח מתוך הפרופיל.\",\n          \"הפריסה נוחה במובייל.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלבנות פרופיל לקוח מלא לבעל העסק ולעובדים.\n\nדרישות:\n- אזורים/טאבים: פרטים, הזמנות, חשבוניות, מדדים ואיפוס סיסמה.\n- פרטים: שם מלא, טלפון, כתובת, עיר והערות משלוח.\n- הצג סיכום הזמנות קשורות.\n- הצג רשימת חשבוניות.\n- הצג מדדי לקוח.\n- הצג פעולת איפוס סיסמה.\n- הוסף יצירת הזמנה במסך מלא עם customer preselected.\n- הוסף modal הזמנה מהיר מתוך הפרופיל.\n- ודא מובייל.\n\nAcceptance criteria:\n- פרופיל לקוח מלא וקריא.\n- כל האזורים שאושרו מופיעים.\n- שני מסלולי יצירת הזמנה עובדים.\n- אין overflow במובייל.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"יצירת הזמנה מתוך לקוח\",\n        branch: \"feat/customer-screen-order-links\",\n        items: [\n          \"מסלול מסך הזמנה מלא נפתח עם הלקוח כבר מסומן.\",\n          \"modal מהיר יכול ליצור הזמנה בסיסית מתוך פרופיל הלקוח.\",\n          \"מסך הלקוח לא משכפל לוגיקת סכומי הזמנה אם היא כבר קיימת במקום אחר.\",\n          \"הערות משלוח לא עוברות אוטומטית.\",\n          \"שגיאות מוצגות בצורה ברורה.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלחבר יצירת הזמנה מתוך פרופיל לקוח בשני מסלולים: מסך מלא ו-modal מהיר.\n\nדרישות:\n- מסך הזמנה מלא נפתח עם הלקוח כבר מסומן.\n- modal מהיר יכול ליצור הזמנה בסיסית מתוך פרופיל הלקוח.\n- אל תשכפל לוגיקת סכומים אם קיימת לוגיקת הזמנות מרכזית.\n- הערות משלוח לא עוברות אוטומטית להזמנה.\n- שגיאת יצירת הזמנה לא משנה מצב כאילו הפעולה הצליחה.\n\nAcceptance criteria:\n- שני המסלולים עובדים.\n- ההזמנה משויכת ללקוח הנכון.\n- שגיאות מוצגות ברור.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"איפוס סיסמה\",\n        branch: \"feat/customer-screen-password-reset\",\n        items: [\n          \"פעולת איפוס קיימת בפרופיל הלקוח.\",\n          \"כל עובד יכול להשתמש בפעולת האיפוס.\",\n          \"האיפוס מגדיר סיסמה זמנית 123456.\",\n          \"הלקוח חייב להחליף סיסמה בכניסה הבאה.\",\n          \"ה-hash של הסיסמה מתעדכן; סיסמה גלויה לא נשמרת.\",\n          \"אחרי האיפוס לא מוצגת סיסמה שמורה.\",\n          \"לא נשלחת הודעה חיצונית, מייל או WhatsApp בשלב הזה.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלהוסיף איפוס סיסמה בטוח ללקוח ששכח סיסמה.\n\nדרישות:\n- כפתור איפוס בפרופיל לקוח.\n- כל עובד יכול לבצע איפוס.\n- האיפוס מגדיר סיסמה זמנית 123456.\n- הלקוח חייב לשנות סיסמה בכניסה הבאה.\n- עדכן password hash ו-must_change_password.\n- אל תשמור או תציג סיסמה plain text.\n- אל תשלח הודעה חיצונית, מייל או WhatsApp.\n\nAcceptance criteria:\n- reset מעדכן את מצב הגישה.\n- must_change_password=true אחרי איפוס.\n- אין חשיפת סיסמה שמורה.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"חשבוניות לקוח\",\n        branch: \"feat/customer-screen-invoices\",\n        items: [\n          \"פרופיל הלקוח מציג חשבוניות.\",\n          \"שדות החשבונית: קישור, מספר חשבונית, תאריך, סכום וסטטוס תשלום.\",\n          \"Meshulam / Grow מסומן כמקור עתידי צפוי.\",\n          \"פרטי אינטגרציית הספק נדחים לשלב מאוחר יותר.\",\n          \"מסך הלקוח לא מנפיק חשבוניות רשמיות.\",\n          \"מצב ריק מוצג בצורה ברורה.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלהציג חשבוניות של לקוח בפרופיל.\n\nדרישות:\n- הצג קישור לחשבונית.\n- הצג מספר חשבונית, תאריך, סכום וסטטוס תשלום.\n- התייחס ל-Meshulam / Grow כמקור עתידי צפוי, אבל אל תממש אינטגרציה חיה עכשיו.\n- מסך הלקוח לא מנפיק חשבוניות רשמיות.\n- הצג empty state ברור כשאין חשבוניות.\n\nAcceptance criteria:\n- חשבוניות מוצגות בפרופיל לקוח.\n- כל השדות שאושרו מופיעים.\n- אין קריאות חיות ל-provider.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"מדדי לקוח\",\n        branch: \"feat/customer-screen-metrics\",\n        items: [\n          \"הפרופיל מציג סך רכישות כולל.\",\n          \"הפרופיל מציג מספר הזמנות.\",\n          \"הפרופיל מציג ממוצע להזמנה.\",\n          \"הפרופיל מציג תאריך הזמנה אחרונה.\",\n          \"המדדים נגזרים מנתוני הזמנות/תשלומים שמורים.\",\n          \"מוצרים קבועים/נפוצים לא מוצגים בשלב הזה.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלהציג מדדי ערך לקוח בפרופיל וברשימה לפי הצורך.\n\nדרישות:\n- הצג סך רכישות כולל.\n- הצג מספר הזמנות.\n- הצג ממוצע להזמנה.\n- הצג תאריך הזמנה אחרונה.\n- חשב את המדדים מנתוני הזמנות/תשלומים שמורים.\n- אל תוסיף מוצרים קבועים/נפוצים.\n\nAcceptance criteria:\n- המדדים נכונים מול נתוני seed/test.\n- אין חישוב כפול לא עקבי.\n- מוצרים נפוצים לא מופיעים.\n- build/tests רלוונטיים עוברים.`\n      },\n      {\n        title: \"בדיקת מובייל ו-RTL\",\n        branch: \"fix/customer-screen-mobile-rtl\",\n        items: [\n          \"רשימת הלקוחות נוחה בטלפון.\",\n          \"פרופיל הלקוח נוח בטלפון.\",\n          \"טופס יצירה/עריכה נוח בטלפון.\",\n          \"modal הזמנה מהיר נוח בטלפון.\",\n          \"דף לקוחות מחוקים נוח בטלפון.\",\n          \"פריסת RTL בעברית תקינה.\",\n          \"שמות ארוכים, כתובות, קישורי חשבוניות והערות לא גולשים מחוץ למסך.\",\n          \"הפעולות המרכזיות נשארות נגישות.\"\n        ],\n        prompt: `אנחנו עובדים על customer-screen בפרויקט Drive Dog.\n\nהמטרה:\nלוודא שמסך הלקוחות נוח ורספונסיבי בטלפון כבר בשלב הראשון.\n\nדרישות:\n- בדוק רשימת לקוחות בטלפון.\n- בדוק פרופיל לקוח בטלפון.\n- בדוק טופס יצירה/עריכה בטלפון.\n- בדוק modal הזמנה מהיר בטלפון.\n- בדוק דף לקוחות מחוקים בטלפון.\n- ודא RTL בעברית.\n- ודא שאין overflow לשמות, כתובות, קישורי חשבוניות והערות.\n- שמור פעולות מרכזיות נגישות.\n\nAcceptance criteria:\n- המסך נוח בטלפון.\n- אין שבירת טקסט/כפתורים.\n- הפעולות המרכזיות זמינות.\n- build/tests רלוונטיים עוברים.`\n      }\n    ];\n\n    const checklist = document.getElementById(\"checklist\");\n\n    tasks.forEach((task, index) => {\n      const section = document.createElement(\"section\");\n      section.className = \"section\";\n      section.innerHTML = `\n        <div class=\"section-head\">\n          <div class=\"section-title\">\n            <h3>${index + 1}. ${task.title}</h3>\n            <span class=\"branch\">${task.branch}</span>\n          </div>\n          <span class=\"status ${task.status === \"בוצע\" ? \"done\" : \"\"}\">${task.status || \"ממתין\"}</span>\n        </div>\n        <div class=\"body\">\n          <ul class=\"acceptance\">\n            ${task.items.map((item) => `<li><span class=\"box\" aria-hidden=\"true\"></span><span>${item}</span></li>`).join(\"\")}\n          </ul>\n          <div class=\"prompt-block\">\n            <div class=\"prompt-title\">פרומפט מוכן לסוכן</div>\n            <pre class=\"prompt-copy\">${task.prompt}</pre>\n          </div>\n        </div>\n      `;\n      checklist.append(section);\n    });\n  </script>\n</body>\n</html>\n";
const demoApiCustomers = [{"id":"c1","firstName":"עמי","lastName":"כהן","phone":"050-1111111","address":"הכלנית 12","city":"ראשון לציון","deliveryNotes":"להתקשר לפני הגעה","mustChangePassword":false,"deletedAt":null,"createdAt":"2026-07-22T00:00:00.000Z","updatedAt":"2026-07-22T00:00:00.000Z"},{"id":"c2","firstName":"דנה","lastName":"לוי","phone":"052-2222222","address":"הגפן 8","city":"רחובות","deliveryNotes":"להשאיר ליד הדלת","mustChangePassword":false,"deletedAt":null,"createdAt":"2026-07-22T00:00:00.000Z","updatedAt":"2026-07-22T00:00:00.000Z"},{"id":"c3","firstName":"יוסי","lastName":"מזרחי","phone":"054-3333333","address":"העצמאות 40","city":"אשדוד","deliveryNotes":"כלב גדול בחצר","mustChangePassword":false,"deletedAt":null,"createdAt":"2026-07-22T00:00:00.000Z","updatedAt":"2026-07-22T00:00:00.000Z"}];
const driveDogLogo = "";

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store"
    }
  });
}

function binaryFromBase64(base64) {
  const raw = atob(base64);
  const bytes = new Uint8Array(raw.length);
  for (let index = 0; index < raw.length; index += 1) bytes[index] = raw.charCodeAt(index);
  return bytes;
}

function normalizePhone(phone) {
  return String(phone ?? "").replace(/[^\d+]/g, "");
}

function normalizeCustomerInput(input, existing = {}) {
  return {
    firstName: String(input.firstName ?? existing.firstName ?? "").trim(),
    lastName: String(input.lastName ?? existing.lastName ?? "").trim(),
    phone: String(input.phone ?? existing.phone ?? "").trim(),
    address: String(input.address ?? existing.address ?? "").trim(),
    city: String(input.city ?? existing.city ?? "").trim(),
    deliveryNotes: String(input.deliveryNotes ?? existing.deliveryNotes ?? "").trim()
  };
}

function validateCustomerInput(input) {
  if (!input.firstName) return "נדרש שם";
  if (!input.lastName) return "נדרש שם משפחה";
  if (!input.phone) return "נדרש טלפון";
  return null;
}

function ensureUniquePhone(customers, phone, customerId) {
  const normalized = normalizePhone(phone);
  return !customers.some((customer) => customer.id !== customerId && normalizePhone(customer.phone) === normalized);
}

async function handleCustomerApi(request, url) {
  const match = url.pathname.match(/^\/api\/customers(?:\/([^/]+))?(?:\/([^/]+))?$/);
  if (!match) return null;
  const [, customerId, action] = match;
  if (request.method === "GET" && !customerId) {
    return json({ customers: demoApiCustomers.filter((customer) => !customer.deletedAt) });
  }
  if (request.method === "GET" && customerId === "deleted" && !action) {
    return json({ customers: demoApiCustomers.filter((customer) => customer.deletedAt) });
  }
  if (request.method === "POST" && !customerId) {
    const input = normalizeCustomerInput(await request.json());
    const validationError = validateCustomerInput(input);
    if (validationError) return json({ error: validationError }, 400);
    if (!ensureUniquePhone(demoApiCustomers, input.phone)) return json({ error: "כבר קיים לקוח עם הטלפון הזה" }, 409);
    const now = new Date().toISOString();
    const customer = { id: "c_" + Date.now().toString(36), ...input, mustChangePassword: false, deletedAt: null, createdAt: now, updatedAt: now };
    demoApiCustomers.push(customer);
    return json({ customer }, 201);
  }
  const customer = demoApiCustomers.find((item) => item.id === customerId);
  if (!customer) return json({ error: "לקוח לא נמצא" }, 404);
  if (request.method === "PATCH" && !action) {
    const input = normalizeCustomerInput(await request.json(), customer);
    const validationError = validateCustomerInput(input);
    if (validationError) return json({ error: validationError }, 400);
    if (!ensureUniquePhone(demoApiCustomers, input.phone, customer.id)) return json({ error: "כבר קיים לקוח עם הטלפון הזה" }, 409);
    Object.assign(customer, input, { updatedAt: new Date().toISOString() });
    return json({ customer });
  }
  if (request.method === "DELETE" && !action) {
    Object.assign(customer, { deletedAt: customer.deletedAt || new Date().toISOString(), updatedAt: new Date().toISOString() });
    return json({ customer });
  }
  if (request.method === "POST" && action === "reset-password") {
    Object.assign(customer, { mustChangePassword: true, updatedAt: new Date().toISOString() });
    return json({ customer });
  }
  return json({ error: "פעולה לא נתמכת" }, 405);
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const apiResponse = await handleCustomerApi(request, url);
    if (apiResponse) return apiResponse;
    if (url.pathname === "/assets/drive-dog-logo.jpg") {
      return new Response(binaryFromBase64(driveDogLogo), {
        headers: {
          "content-type": "image/jpeg",
          "cache-control": "no-store"
        }
      });
    }
    const html = url.pathname === "/" || url.pathname.startsWith("/admin")
      ? adminHtml
      : url.pathname.startsWith("/proposal")
        ? proposalHtml
        : url.pathname.startsWith("/questionnaire")
          ? questionnaireHtml
          : url.pathname.startsWith("/customer-screen-checklist")
            ? customerScreenChecklistHtml
            : adminHtml;

    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store"
      }
    });
  }
};
